(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-coba-rl-capability-oriented-budget-a-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-1\">一 · 现场：一条被长尾拖住的 rollout 流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-2\">二 · 旧方案的三根支柱与它们的接缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-3\">三 · 为什么非改不可：解耦部署把接缝撕开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-4\">四 · 一个具体例子：同一批里的三类样本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-5\">五 · 异步流水线的版本对齐与陈旧度代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-6\">六 · 量化档位缺席下的判断边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-7\">七 · 在线服务里被统一预算拖垮的那条长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-8\">八 · 测量口径：把“负载形态”拆成可核验的四个量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-9\">九 · 负载如何塑造方案：长尾样本独占批资源是核心矛盾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-10\">十 · 方案反过来限制负载：配额改变了到达过程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-11\">十一 · 预算函数在负载坐标下的读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-12\">十二 · 可核查的监控清单与失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-13\">十三 · 长尾配额队列：方案边界、失效条件与可核查口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-14\">十四 · 预算函数落进 kernel 之前：数值路径必须与调度路径同构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-15\">十五 · 核心 kernel 的 dtype 谱系与累加精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-16\">十六 · tcgen05、TMEM 与 2-SM MMA：大配额样本的算力落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-17\">十七 · 采样数值路径与验证器的一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-18\">十八 · 量化档位缺失下的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-19\">十九 · 能力预算落地的算子边界：配额、前缀复用与数值路径一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-20\">二十 · 显存账本的三个账户与预算函数的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-21\">二十一 · 分页与 KV 复用的字节级代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-22\">二十二 · 卸载与带宽瓶颈的定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-23\">二十三 · 一个可复算的显存预算流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-24\">二十四 · 长尾队列、离策略陈旧度与显存回收的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-25\">二十五 · 验证侧显存与生成侧显存的分离账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-26\">二十六 · 连续批处理与预算配额组批</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-27\">二十七 · Chunked prefill 与前缀 KV 复用的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-28\">二十八 · 优先级、抢占与长尾配额队列</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-29\">二十九 · 分离式预填/解码与验证服务的独立推理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-30\">三十 · 时延与吞吐的取舍，尾延迟怎么压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-31\">三十一 · 异步流水线与调度层的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-32\">三十二 · 配额队列的边界：能力预算在调度层的失效条件与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-33\">三十三 · 并行拓扑：把 CoBA-RL 的预算落到切分维度上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-34\">三十四 · NVLink 5 与 NVSwitch：All-to-All 是 EP 的真实成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-35\">三十五 · NIXL 传输：验证服务解耦后的数据面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-36\">三十六 · 通信何时成为瓶颈：三个可判定的信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-37\">三十七 · 切分选择与预算函数的联合调参</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-38\">三十八 · 预算分配落进并行拓扑之后的通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-39\">三十九 · 精度塌陷：预算函数在低精度采样路径上的失稳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-40\">四十 · OOM 与显存抖动：前缀 KV 复用与配额队列的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-41\">四十一 · 批抖动：阈值与温度联合调参的稳定性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-42\">四十二 · 尾延迟与静默降级：长尾队列深度作为主监控量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-43\">四十三 · 定位与回滚：版本对齐点作为回滚锚</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-44\">四十四 · 失效面：预算函数的三个断点与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-45\">四十五 · 口径的第一性问题：这篇论文没有可比的绝对数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-46\">四十六 · 模型与负载口径：能力估计是隐变量，不是基准配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-47\">四十七 · 硬件档位口径：没有档位就没有 NVFP4 结论</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-48\">四十八 · batch 与并发口径：配额组批改变的是批的构成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-49\">四十九 · 指标口径：TTFT/TPOT/吞吐/显存/功耗各自被什么改变</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-50\">五十 · 不可比清单：哪些提升不能跨论文、跨档位相加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-51\">五十一 · 迁移的第一道坎：能力估计从哪里来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-52\">五十二 · 验证预算迁移：验证器换掉之后配额要重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-53\">五十三 · 长尾配额与 SLO 的联合调参：迁移时阈值必须重估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-54\">五十四 · 异步流水线与离策略陈旧度：迁移到高同步频率场景要改</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-55\">五十五 · 规模上限：这套方案在哪里先失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-56\">五十六 · 不适用的边界与迁移判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-57\">五十七 · 迁移到别的模型与领域时要动哪三处</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:551px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 551.0 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入 rollout 引擎，按样本能力估计分配生成预算与验证预算。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批量调度器按预算配额组批，长尾样本进入受限配额队列避免独占批资源。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成阶段复用前缀 KV，减少重复预填并保持采样数值路径一致。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">候选送入奖励模型与验证器推理服务，按验证预算做打分与筛选。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">异步流水线回传结果，权重同步点对齐版本并记录离策略陈旧度。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"469.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">监控长尾队列深度与吞吐，超阈值时收缩困难样本预算。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-1\">一 · 现场：一条被长尾拖住的 rollout 流水线</h3>\n<p>设想一个已经上线的推理集群：rollout 引擎与训练进程解耦，前者在 N 个推理实例上批量生成候选，后者在另一组 GPU 上消费这些候选做策略更新。请求进入 rollout 引擎时，调度器按固定批大小组批，每个样本被赋予统一的生成 token 上限——比如一律 4K token、一律一次验证。这个形态在平均长度可控时跑得不错，但真实流量里总有一撮样本：数学题需要长链推理、代码题要反复试错、多轮对话要维持长上下文。它们不是多数，却决定了整批的完成时间。</p>\n<p>痛点在于统一预算与样本能力之间的错配。简单样本几百 token 就收敛，却仍被预留 4K 配额，KV cache 按上限预分配、批槽位按上限占用，算力被白白锁死；困难样本在 4K 处被截断，候选质量不足，验证器打回，下一轮再采样，等效于欠采样。更糟的是批级同步：一个超长样本占着批槽不放，整批必须等它结束才能回收，吞吐被单个样本的长尾拉低。这不是调度器不够聪明，而是预算这个变量根本没有进入调度决策——批大小、KV 分配、验证次数都是常量。</p>\n<p>代价可以拆成三块。显存侧，KV cache 按统一上限预留，长尾样本的 KV 增长直接压缩同批其他样本的可用槽位，批利用率下降；带宽侧，前缀重复预填在统一预算下无法按样本裁剪，重复的 prefill 计算挤占 HBM 带宽；延迟侧，批完成时间由批内最慢样本决定，长尾队列深度上升时 P99 延迟被拖长。三者互相放大：批利用率下降促使调度器增大批大小，批越大长尾越容易混入，P99 越差。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-2\">二 · 旧方案的三根支柱与它们的接缝</h3>\n<p>论文之前的主流做法可以概括为三根支柱：统一 token 预算、统一验证次数、批级同步回收。统一 token 预算把生成长度当作超参而非样本属性，好处是实现简单、批形状规整、KV 预分配可预测；代价是预算与难度脱钩。统一验证次数意味着每个候选都过一次奖励模型或验证器，验证算力与生成算力按固定比例绑定，简单样本的验证是纯开销。批级同步回收则保证语义简单：一批全部完成才进入下一批，权重版本一致、离策略程度可控。</p>\n<p>接缝出现在两个地方。其一是长尾：批级同步把最慢样本的延迟摊给整批，长尾比例稍高，批利用率就塌陷。其二是异步化：一旦为了吞吐把 rollout 与训练解耦成异步流水线，权重同步点之间的候选就带有离策略陈旧度，统一预算无法区分“这个样本值得多验证几次以抵消陈旧”与“这个样本早已掌握、不必再花算力”。旧方案没有表达“按样本分配算力”的语言，只能用全局旋钮——调大批大小、调低验证频率、调短生成长度——每个旋钮都在牺牲另一端的指标。</p>\n<table class=\"mini\"><thead><tr><th>旧方案要素</th><th>实现代价</th><th>失效场景</th></tr></thead><tbody><tr><td>统一 token 上限</td><td>KV 按上限预留，批槽位固定</td><td>长度分布双峰，简单样本浪费、困难样本截断</td></tr><tr><td>统一验证次数</td><td>验证算力与生成算力绑定</td><td>简单样本验证成纯开销，边界样本验证不足</td></tr><tr><td>批级同步回收</td><td>语义简单、版本一致</td><td>单个超长样本拖垮整批 P99</td></tr></tbody></table>\n<p>这三者的共同点是：预算是一个全局常量，而不是样本级变量。只要预算不进调度决策，长尾就只能靠“限制并发”或“截断长度”这类粗暴手段压制，吞吐与质量的权衡被迫在全局层面做，无法落到单个样本上。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-3\">三 · 为什么非改不可：解耦部署把接缝撕开</h3>\n<p>解耦部署是趋势：rollout 引擎要独立扩缩容、独立选量化档位、独立做前缀缓存，训练侧则要稳定占用高带宽互联做梯度同步。一旦两侧解耦，rollout 侧就不再受训练步的严格节拍约束，异步流水线让候选在权重版本之间流动。此时统一预算的第二个接缝被放大：离策略陈旧度是样本相关的——一个边界样本在陈旧权重下采样，候选质量方差大，需要更多验证次数才能筛出可用信号；一个已掌握样本在同样陈旧度下几乎不受影响。统一验证次数对前者不足、对后者过剩。</p>\n<p>用预算函数的形式表达这个诉求是自然的。设样本 $i$ 的能力估计为 $c_i$，阈值 $\\tau$ 划分“已掌握”与“能力边界”，温度 $T$ 控制过渡带宽度，则生成预算</p>\n<div class=\"formula\">$$\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)$$</div>\n<p>把预算压到区间 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$ 内：$c_i \\ll \\tau$ 的样本拿到接近下限的配额，快速生成、快速验证、快速回收；$c_i \\approx \\tau$ 的样本拿到接近上限的配额与多次验证。这个映射的工程意义不在于公式本身，而在于它把“预算”变成了调度器可读的样本级字段——批大小、KV 预留、验证队列深度都可以按这个字段分组。</p>\n<p>代价也随之转移。显存侧，KV 预留从“按全局上限”变为“按样本配额”，长尾样本的 KV 增长被配额约束在队列内，不再无条件挤占同批槽位；吞吐侧，简单样本快速回收释放批槽，批利用率上升；延迟侧，长尾样本进入受限配额队列，单个超长样本无法独占批资源，整批等待被切断。代价是调度复杂度：分组组批、配额队列、验证服务独立扩缩容，都是新增的工程面。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-4\">四 · 一个具体例子：同一批里的三类样本</h3>\n<p>取一个混合批：二十个短问答、五个中等数学题、一个需要长链推导的竞赛题。旧方案下，调度器按统一 4K 上限组批，KV 按 4K 预留，批槽位被二十六个样本平摊。竞赛题跑到 3.8K 才收敛，整批等它；五个数学题里有两个在 4K 处被截断，验证器打回后重采样，等效欠采样；二十个短问答各用不到 500 token，却占着 4K 的 KV 预留，批利用率被虚高占用压低。</p>\n<p>按能力预算分配后，调度器读取 $c_i$：短问答落在 $\\tau$ 以下，配额压到 $\\mathcal{B}_{\\min}$ 附近，生成几百 token 即送验证，一次通过后立刻回收槽位；数学题落在过渡带，配额居中、验证两次；竞赛题配额接近 $\\mathcal{B}_{\\max}$，但被放进受限配额队列，独占一个受限槽位而非拖住整批。结果是短问答的批槽快速周转，数学题获得足够长度与验证次数，竞赛题在配额内跑完而不阻塞其他样本。长尾队列深度成为监控项：队列变深说明困难样本积压，下一轮预算收缩或扩容验证服务；队列变浅说明配额过松，可扩张边界样本预算。</p>\n<p>这个例子里没有出现任何新的硬件能力，变化全在调度层：预算从常量变成样本级字段，批从“等最慢”变成“按配额分组回收”，验证从绑定生成变成独立服务按配额调用。前缀 KV 复用在生成阶段保留，候选经共享前缀预填后送入验证器，避免重复 prefill 挤占带宽——这是把预算分配落到前缀共享层的具体动作。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-5\">五 · 异步流水线的版本对齐与陈旧度代价</h3>\n<p>解耦部署绕不开权重同步。异步流水线在同步点做版本对齐：rollout 侧产出的候选携带生成时的权重版本号，训练侧消费前检查版本差；若离策略陈旧度超过阈值，候选被丢弃并重排预算。这一步是统一预算方案里没有的——旧方案靠批级同步天然保证版本一致，代价是吞吐；异步化用吞吐换版本漂移，就必须用样本级预算去补偿漂移带来的质量方差。</p>\n<p>工程代价在这里最集中：丢弃过期候选意味着算力浪费，重排预算意味着调度器要在同步点做一次批量重算；同步频率过低，陈旧度放大，边界样本的候选质量方差变大，验证预算被迫上调；同步频率过高，流水线退化为准同步，解耦的吞吐收益被吃掉。论文材料未给出具体阈值与同步频率，可核验的只是“超阈值丢弃并重排”这一机制存在。对容量规划而言，这意味着监控项必须包含离策略陈旧度与长尾队列深度两个维度，前者决定验证预算的下限，后者决定生成预算的上限。</p>\n<p>还有一个隐性代价：能力估计 $c_i$ 的更新方式未说明，冷启动阶段预算分配偏向均匀配额，等于退回旧方案。若能力估计滞后于策略变化，边界样本可能被误判为已掌握而欠采样，或已掌握样本被误判为边界而过度采样。这是预算函数之外的第二层风险，落在监控与重估频率上，而不是公式本身。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-6\">六 · 量化档位缺席下的判断边界</h3>\n<p>把这条流水线放到 Blackwell 上，预算分配与数值精度是两条正交的工程线，但会在采样稳定性上相交。生成阶段若走 NVFP4/FP8 路径，采样数值路径与验证器的数值路径必须一致，否则预算分配带来的质量收益会被采样偏差抵消——简单样本因数值抖动被误判为未通过，配额被反复消耗；边界样本的多次验证若跨不同量化档位，分数不可比。论文材料未给出量化方案与硬件档位，NVFP4 下采样稳定性与显存占用无法核验，这是评估实际吞吐收益前必须补齐的一块。</p>\n<p>可核验的工程判断只有调度机制层面：预算函数把能力估计映射到生成配额区间，调度器按配额分组组批，长尾样本进受限队列，验证算力与生成算力分离并由独立服务承接，异步流水线在同步点做版本对齐并按陈旧度丢弃重排。这些机制在解耦部署形态下成立，不依赖具体硬件档位；但吞吐收益的大小取决于长尾比例、SLO 目标与量化路径的一致性，三者材料均未给出。对读者而言，可迁移的是“把预算变成样本级字段并落到批调度与前缀共享层”这一结构，而不是任何具体数字。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-7\">七 · 在线服务里被统一预算拖垮的那条长尾</h3>\n<p>设想一个已上线的推理服务：rollout 引擎与训练侧解耦，前端持续灌入长度分布极不均匀的请求，批调度器按到达顺序组批，每个样本无论难易都拿到同一份生成 token 配额与同一份验证次数。系统在稳态下看起来吞吐不错，但一旦长尾请求进入队列，单个超长样本就会把整批的完成时间拉到最慢者的水平——批内其余样本的算力已经付了，却只能等它。与此同时，简单样本被过度采样、被反复送进验证器打分，验证服务与生成服务争抢同一批算力，前缀 KV 复用的收益被长尾的重复预填抵消。这就是统一预算分配在部署形态下的真实代价：它不是算力不够，而是算力被均匀地摊到了不需要它的地方。</p>\n<p>把这种代价写成可核算的形式，设批内样本数为 $n$，样本 $i$ 的生成预算为 $B_i$、验证次数为 $V_i$，则一批的完成时间近似由最大者支配：</p>\n<div class=\"formula\">$$T_{\\text{batch}}\\approx \\max_{i\\in\\text{batch}}\\left(\\frac{B_i}{r_{\\text{gen}}}+\\frac{V_i}{r_{\\text{ver}}}\\right),\\qquad \\text{util}=\\frac{\\sum_i (B_i+V_i)}{n\\cdot T_{\\text{batch}}\\cdot (r_{\\text{gen}}+r_{\\text{ver}})}$$</div>\n<p>统一预算意味着 $B_i\\equiv B$、$V_i\\equiv V$，长尾样本的 $B_i/r_{\\text{gen}}$ 单项就把 $T_{\\text{batch}}$ 顶高，而 util 随长尾比例上升单调下降。更隐蔽的代价在异步流水线：权重同步点之间，候选由旧版本策略生成，离策略陈旧度随批等待时间线性增长，长尾越拖，陈旧度越大，采样偏差被放大到验证器无法纠正的程度。此时增加并发或加大批并不能救场，只会让更多样本陪跑。</p>\n<p>这套旧做法的失效边界很清晰：当请求长度分布集中、验证成本远低于生成成本时，统一预算的浪费有限；一旦长尾比例上升、验证器本身成为独立服务且与生成共享算力，均匀配额就从“简单”变成“结构性瓶颈”。CoBA-RL 的切入点正是把预算从均匀改为按能力估计 $c_i$ 映射，经阈值 $\\tau$ 与温度 $T$ 平滑落到 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$，并把长尾样本关进受限配额队列——代价是阈值与温度需与 SLO 联合调参，配额过紧会欠采样困难样本，过松则吞吐收益归零；而材料未给出硬件档位与量化方案，NVFP4 下采样数值路径与验证器不一致时，预算分配的收益会被采样偏差抵消，这一点在部署前必须自行核验。</p>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-8\">八 · 测量口径：把“负载形态”拆成可核验的四个量</h3>\n<p>讨论 CoBA-RL 的预算分配之前，必须先固定负载的测量口径，否则“长尾拖慢吞吐”只是一句无法反驳的断言。对 rollout 引擎而言，可核验的负载描述至少包含四个互相耦合的量：输入长度分布、并发请求数、批大小、SLO 目标。四者不是独立参数，而是同一条排队链上的不同截面。</p>\n<p>输入长度分布用分位数刻画，而不是均值。记第 $i$ 个样本的 prompt 长度为 $L^{\\text{in}}_i$、生成 token 数为 $L^{\\text{out}}_i$，则单样本的预填代价近似正比于 $L^{\\text{in}}_i$、解码代价正比于 $L^{\\text{out}}_i$。均值会被少数超长样本拉偏，工程上应记录 $P_{50}$、$P_{90}$、$P_{99}$ 与最大值，并单独统计“超过批内中位长度 $k$ 倍”的样本占比，这就是长尾比例的可核查定义。</p>\n<div class=\"formula\">$$\\text{长尾占比}=\\frac{\\#\\{i: L^{\\text{in}}_i &gt; k\\cdot \\mathrm{median}(L^{\\text{in}})\\}}{N},\\quad k\\ \\text{需在监控中固定}$$</div>\n<p>并发与批大小要分开记：并发是调度器同时持有的活跃请求数，批大小是单次前向实际拼进的序列数。二者之间隔着显存与 KV 预算这道闸门，因此“并发上限”与“有效批利用率”是两个指标。批利用率可定义为实际参与计算的 token 槽位占分配槽位的比例，长尾样本占着槽位却让同批其他序列空等，正是批利用率下降的直接来源。</p>\n<p>SLO 目标应写成可判定的形式，例如“$P_{95}$ 端到端延迟不超过某阈值”或“每轮 rollout 批次在给定墙钟窗口内完成”。没有这个约束，预算分配就退化为“尽量多算”，而 CoBA-RL 的全部张力恰恰来自 SLO 有限。具体数值论文未给出，因此工程上必须自行标定，并把标定结果写进监控，而不是引用外部数字。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-9\">九 · 负载如何塑造方案：长尾样本独占批资源是核心矛盾</h3>\n<p>在 rollout 与训练解耦的部署形态下，负载形态直接决定预算函数该往哪个方向偏。若输入长度分布窄、并发高、批容易拼满，统一预算尚可维持吞吐；一旦长尾比例上升，单个超长样本会把整批的解码步拖到它的长度，同批短样本被迫陪跑。这就是同步批处理的经典代价：批的完成时间由批内最慢成员决定。</p>\n<p>设批内有 $n$ 个样本，第 $i$ 个样本的解码步数为 $s_i$，则同步批的墙钟代价近似为 $\\max_i s_i$ 乘以单步时间，而有效吞吐为 $\\sum_i s_i / \\max_i s_i$ 乘以单步吞吐。当 $s_i$ 的分布重尾时，这个比值随批大小增大而恶化。CoBA-RL 的对策不是消除长尾，而是把长尾样本放进受限配额队列：单个超长样本不能无限占用批槽位，从而把 $\\max_i s_i$ 对整批的绑架作用限制在配额之内。</p>\n<div class=\"formula\">$$\\text{批有效吞吐}\\approx \\frac{\\sum_{i\\in\\text{batch}} s_i}{\\max_{i\\in\\text{batch}} s_i}\\cdot \\text{单步吞吐},\\quad \\text{长尾使分子固定、分母膨胀}$$</div>\n<p>具体例子：一个批里 7 个样本各需 200 步解码、1 个样本需 4000 步，同步批要跑满 4000 步，前 7 个样本的槽位在后 3800 步里几乎空转。若把该长尾样本移入受限配额队列、以更小批单独推进，主批可在 200 步后释放并接纳新请求，代价是长尾样本自身的完成时间被拉长。这就是吞吐与长尾延迟之间的显式交换，也是预算分配必须与批调度联动的理由。</p>\n<p>并发维度上还有一层：验证器服务是独立推理服务，生成侧与验证侧的负载形态并不相同。生成侧是自回归解码、长尾在输出长度；验证侧是一次前向打分、长尾在候选数量与输入拼接长度。CoBA-RL 把验证预算按样本分配，等于在验证侧也引入配额，避免能力边界样本的多次验证把验证服务队列压穿。两侧的 SLO 应分别标定，混在一起统计会掩盖真正的瓶颈。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-10\">十 · 方案反过来限制负载：配额改变了到达过程</h3>\n<p>预算分配不是被动适应负载，它会重塑负载的统计形态，这一点在容量规划时最容易被忽略。调度器按能力估计给出生成 token 配额后，实际进入解码阶段的序列长度分布被截断在 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$ 区间内，长尾被配额削平。于是监控看到的 $P_{99}$ 长度会下降，但这不等于底层请求变短了，而是被配额挡在了队列里。</p>\n<p>由此产生一个可核查的陷阱：若只看解码侧的长度分位数，会误判系统已经“驯服”了长尾；真正的长尾压力转移到了受限配额队列的深度上。CoBA-RL 的监控项明确包含长尾队列深度与批利用率，正是为了捕捉这种转移。工程判断应是：长度分位数下降而队列深度上升，说明配额偏紧，困难样本在被欠采样；反之队列深度下降而批利用率下降，说明配额偏松，长尾重新侵入主批。</p>\n<div class=\"formula\">$$\\text{配额紧度信号}=\\Delta\\,\\text{长尾队列深度}\\ \\text{与}\\ \\Delta\\,\\text{批利用率}\\ \\text{的符号组合}$$</div>\n<p>另一个反向限制来自异步流水线的版本对齐。权重同步点会周期性打断 rollout，若同步频率低，离策略陈旧度上升，过期候选被丢弃并重排预算，等效于把已经花掉的生成算力作废。这在负载上表现为“重排风暴”：一批候选集中失效，队列瞬时加深。容量规划必须为这种周期性尖峰留出余量，而不是按平均吞吐配置。论文未给出具体阈值与同步频率，因此这一项只能作为必须自测的参数暴露在监控里。</p>\n<p>具体例子：某轮批次中能力边界样本获得较大生成预算与多次验证，若恰好在权重同步点前完成生成、同步点后才进入验证，版本不一致导致候选被丢弃，该样本的生成预算与验证预算双双浪费。调度器若在重排时再次给它大预算，就形成正反馈，长尾队列越排越长。可控的做法是把预算重排与版本对齐绑定：同步点后先收缩边界样本预算，待队列消化后再扩张。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-11\">十一 · 预算函数在负载坐标下的读法</h3>\n<p>把预算函数放回负载坐标系，才能看清阈值 $\\tau$ 与温度 $T$ 的工程含义。能力估计 $c_i$ 经 $\\sigma((c_i-\\tau)/T)$ 映射到 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$，$\\tau$ 决定“哪些样本被视为已掌握”，$T$ 决定过渡带的宽度。在负载层面，$\\tau$ 偏低会让更多样本拿到大预算，长尾队列变长、批利用率下降；$\\tau$ 偏高则简单样本配额过小，能力边界样本被欠采样，采样稳定性受损。</p>\n<div class=\"formula\">$$\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)$$</div>\n<p>$T$ 的作用更微妙：$T$ 大则预算随能力平滑变化，批内预算差异小，组批容易、批利用率高，但算力从简单样本向边界样本的转移不锐利；$T$ 小则预算接近二值化，组批出现明显的长短批分裂，调度器需要按预算配额分桶组批，桶间负载不均会推高长尾队列深度。论文未量化 $\\tau$ 与 $T$ 的敏感性，因此这两个参数必须与 SLO 联合调参，而不是当作超参随手设定。</p>\n<p>组批策略由此派生：按预算配额分桶，同桶内样本长度相近，$\\max_i s_i$ 与 $\\sum_i s_i$ 的比值改善；跨桶混批则重新引入长尾绑架。代价是桶内并发不足时批利用率下降，尤其在小并发场景下桶化会碎片化批。工程判断是：并发高时桶化收益明显，并发低时应放宽桶边界、允许跨桶混批并依赖受限配额队列兜底。这一取舍没有论文数字支撑，只能由部署方按自身并发分布标定。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-12\">十二 · 可核查的监控清单与失败模式</h3>\n<p>把上述口径落成监控项，才能让“负载塑造方案、方案限制负载”这个循环可观测。建议的最小集合如下表，每一项都对应一个可判定的工程动作，而不是笼统的“观察”。</p>\n<table class=\"mini\"><thead><tr><th>监控项</th><th>测量口径</th><th>触发的工程动作</th></tr></thead><tbody><tr><td>输入长度分位数</td><td>$P_{50}/P_{90}/P_{99}$ 与长尾占比</td><td>长尾占比升则收紧 $\\mathcal{B}_{\\max}$ 或加严配额</td></tr><tr><td>批利用率</td><td>实算 token 槽位 / 分配槽位</td><td>下降则检查桶化碎片或长尾侵入</td></tr><tr><td>长尾队列深度</td><td>受限配额队列的待处理样本数</td><td>持续上升则收缩困难样本预算</td></tr><tr><td>离策略陈旧度</td><td>候选版本与当前权重的差</td><td>超阈值则丢弃过期候选并重排预算</td></tr><tr><td>验证服务队列</td><td>待打分候选数与 $P_{95}$ 等待</td><td>上升则下调边界样本验证次数配额</td></tr></tbody></table>\n<p>失败模式有三条值得单独列出。其一，长尾配额过紧会欠采样困难样本，能力边界样本的多次验证被砍掉，采样稳定性下降，表现为训练侧梯度噪声上升；配额过松则失去吞吐收益，长尾重新独占批资源。其二，异步流水线权重同步频率过低会放大离策略陈旧度，预算重排若不同步联动，会形成前述的重排风暴。其三，若量化方案未定，NVFP4 下采样数值路径与验证器不一致，预算分配带来的吞吐收益可能被采样偏差抵消，而这一项论文未给出配置，无法核验。</p>\n<p>最后落在机制上：CoBA-RL 的负载治理不是单一旋钮，而是预算函数、配额队列、桶化组批、版本对齐四者共享同一组监控信号。任何一项单独调优都会把压力转移到另一项——收紧配额把长尾推进队列，桶化组批把碎片推进批利用率，降低同步频率把偏差推进陈旧度。可核查的做法是让这四项指标同屏呈现，按符号组合而非单指标绝对值做决策，并把 $\\tau$、$T$、配额上限、同步频率作为一组联合标定参数写入部署配置，而不是分散在各处默认值里。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-13\">十三 · 长尾配额队列：方案边界、失效条件与可核查口径</h3>\n<p>CoBA-RL 的吞吐收益几乎全部押在“受限配额队列”这一机制上：调度器按预算函数给出每个样本的生成 token 配额，长尾样本不得越过配额占用批资源，从而避免单个超长样本把整批拖入等待。代价是可量化的——设批内样本数为 $n$，第 $i$ 个样本的配额为 $\\mathcal{B}_i$，批的有效占用近似为 $\\sum_i \\min(L_i,\\mathcal{B}_i)$ 与 $\\max_i \\min(L_i,\\mathcal{B}_i)$ 的折中：前者决定显存与 KV 占用，后者决定批完成时间。配额收紧会压低长尾等待，但把超出配额的 token 推入后续轮次，等价于用采样次数换单批时延。这里的工程判断是：配额队列的收益必须与 SLO 联合标定，脱离 SLO 谈配额只会把长尾从批内转移到批间。</p>\n<p>失效条件集中在三处。其一，能力估计冷启动阶段预算趋近均匀配额，配额队列退化为普通组批，长尾保护失效；其二，长尾配额过紧会欠采样困难样本，能力边界样本的验证预算被摊薄，采样稳定性下降；其三，异步流水线在权重同步点做版本对齐，若同步频率过低，离策略陈旧度超阈值触发丢弃与预算重排，被丢弃候选的已消耗生成算力直接变成吞吐损失——材料未给出该阈值，因此这条代价只能定性评估。此外，材料未给出量化方案，若 NVFP4 采样数值路径与独立验证器不一致，预算分配带来的收益会被采样偏差抵消，这是无法从调度机制层面排除的风险。</p>\n<p>可核查的测量口径应固定在三项监控上，均来自论文明确记录的监控侧：长尾队列深度（排队等待的受限样本数）、批利用率（有效占用与配额上限之比）、离策略陈旧度（候选版本与当前权重的偏差）。三者需与预算函数的 $\\tau$、$T$ 联合记录，否则无法区分收益来自配额还是来自能力估计。下表给出机制与代价的对应关系，供容量规划时逐项核对。</p>\n<table class=\"mini\"><thead><tr><th>机制</th><th>直接代价</th><th>可核查指标</th></tr></thead><tbody><tr><td>受限配额队列</td><td>长尾 token 跨批累积，批间时延上升</td><td>长尾队列深度、批利用率</td></tr><tr><td>验证预算按样本分配</td><td>验证服务独立扩容，算力与生成分离</td><td>验证次数配额执行率</td></tr><tr><td>权重同步点版本对齐</td><td>过期候选丢弃，已耗算力沉没</td><td>离策略陈旧度</td></tr></tbody></table>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-14\">十四 · 预算函数落进 kernel 之前：数值路径必须与调度路径同构</h3>\n<p>CoBA-RL 的预算函数把能力估计 $c_i$ 映射成生成 token 配额，调度器据此组批。但配额只是字节层面的约束，真正决定一次 rollout 能否兑现该配额的，是生成 kernel 在给定 dtype 下的数值行为。若简单样本拿到小配额、边界样本拿到大配额，两者却走不同的量化路径（例如短序列走 BF16、长序列走 FP8），那么同一策略在两类样本上的采样分布不再可比，能力估计 $c_i$ 的更新会被数值噪声污染。工程上必须保证：预算分配改变的只是“生成多少 token、验证几次”，而不是“用什么数值精度生成”。前缀 KV 复用尤其危险——复用段与新增段若精度档位不一致，注意力分数在拼接处出现系统性偏移，长尾样本恰好最容易触发这种拼接。</p>\n<div class=\"formula\">$$\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)$$</div>\n<p>逐项解释：$\\mathcal{B}_{\\min}$ 是保底配额，对应“已掌握样本”仍需的最小生成量，低于它无法构成有效候选；$\\mathcal{B}_{\\max}$ 是边界样本的上限，防止单个样本无限扩张；$\\sigma(\\cdot)$ 提供平滑过渡，使 $c_i$ 在 $\\tau$ 附近时配额连续变化，避免组批时出现配额断崖导致批内 token 数方差过大；$T$ 是温度，$T$ 越小映射越接近阶跃，调度器组批越容易但批内负载越不均，$T$ 越大则相反。$\\tau$ 是能力阈值，决定“算力从已掌握样本转移出去”的拐点。这个公式本身不含任何 dtype 信息，这正是问题所在：它假设配额与数值精度正交，而实际部署中两者通过 kernel 选择耦合。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-15\">十五 · 核心 kernel 的 dtype 谱系与累加精度</h3>\n<p>Blackwell 推理栈的 dtype 谱系是 FP16 / BF16 / FP8（E4M3 与 E5M2）/ NVFP4。对 CoBA-RL 这类 rollout 生成，关键 kernel 有三类：注意力（含 KV 拼接与前缀复用）、GEMM（投影与 MLP）、以及采样前的 logits 归一化。三者的累加精度要求不同。GEMM 在第五代 Tensor Core 上以 FP8 或 NVFP4 输入、FP32 累加，累加器宽度决定了长 K 维度下的误差累积；注意力 softmax 前的分数若以低精度累加，长上下文下 max 减法后的指数项动态范围会被压缩。NVFP4 的块级缩放（每若干元素共享一个指数）在 KV 复用场景下尤其敏感：复用段与新增段若分属不同缩放块边界，拼接后的量化网格不对齐，等效于在注意力分数上叠加了一个分段常数偏移。</p>\n<p>代价侧：FP8 相对 BF16 把 GEMM 的权重带宽减半，KV cache 若以 FP8 存储则显存占用减半，直接放宽了长尾样本的常驻批容量；NVFP4 进一步把权重压到 4 bit，但需要额外的缩放因子存储与反量化指令，在小 batch、短序列的解码阶段，反量化开销可能吃掉带宽收益。对 CoBA-RL 而言，边界样本获得大配额意味着更长的解码步数，解码是 memory-bound 的，权重带宽收益在这里最明显；而简单样本快速通过验证，其生成步数少，量化收益被摊薄。因此量化档位的选择应与预算分布匹配，而不是全局统一。</p>\n<table class=\"mini\"><thead><tr><th>dtype</th><th>典型用途</th><th>累加</th><th>对预算分配的耦合点</th></tr></thead><tbody><tr><td>BF16</td><td>注意力分数、归一化</td><td>FP32</td><td>数值路径基准，能力估计可比</td></tr><tr><td>FP8 E4M3</td><td>GEMM 输入、KV 存储</td><td>FP32</td><td>KV 显存减半，放宽长尾批容量</td></tr><tr><td>NVFP4</td><td>权重、部分激活</td><td>FP32</td><td>块缩放边界须与 KV 复用段对齐</td></tr></tbody></table>\n<p>具体例子：一个边界样本获得 $\\mathcal{B}_{\\max}$ 配额，解码 512 步，每步都要读全部权重。若权重为 NVFP4，权重带宽约为 BF16 的四分之一，单步解码的权重读取时间显著下降，这正是大配额样本受益最大的地方；反之一个 $\\mathcal{B}_{\\min}$ 配额的简单样本只解码数十步，量化带来的固定开销（缩放因子加载、反量化流水）占比更高，收益被稀释。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-16\">十六 · tcgen05、TMEM 与 2-SM MMA：大配额样本的算力落点</h3>\n<p>Blackwell 的 tcgen05 指令族把矩阵乘的累加器放在 TMEM（Tensor Memory）而非寄存器堆，2-SM MMA 让一对 SM 协同完成一次更大的 MMA，共享操作数。对推理的直接含义是：单次 MMA 的 K 维与 N 维可以更大，累加器驻留 TMEM 减少了寄存器压力，使得大 batch、长序列的 GEMM 能以更高占用率运行。CoBA-RL 的批调度把边界样本聚成一批、给大配额，恰好制造了“批内 token 数高、序列长”的形态，这是 2-SM MMA 与 TMEM 累加最擅长的场景；而长尾样本被限制在受限配额队列，批内形态碎片化，2-SM 配对的收益下降，甚至因配对失败退化为单 SM MMA。</p>\n<p>代价侧：TMEM 是有限资源，累加器占用 TMEM 的 tile 数直接限制同时驻留的 MMA 数量。当批内序列长度方差大时，调度器若按最大配额分配 TMEM tile，短样本会浪费 TMEM 容量，降低并发；若按平均配额分配，长样本触发 tile 复用与溢出，增加同步开销。这与预算函数的 $T$ 参数直接相关：$T$ 小则批内配额方差大，TMEM 分配越难均衡；$T$ 大则批内配额趋同，TMEM 利用率高但算力转移效果弱。工程判断是：TMEM 容量应作为组批的硬约束写入调度器，而不是事后由 kernel 自行处理溢出。</p>\n<p>具体例子：调度器把若干 $c_i&gt;\\tau$ 的边界样本组批，每样本配额接近 $\\mathcal{B}_{\\max}$，序列长度相近，2-SM MMA 配对成功率高，TMEM 累加器 tile 按统一形状分配，批利用率高；同一批中若混入一个长尾样本，其配额被受限队列截断，序列长度与批内其他样本不齐，MMA 形状被迫取最大公约，短样本的 TMEM tile 闲置。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-17\">十七 · 采样数值路径与验证器的一致性</h3>\n<p>CoBA-RL 把验证预算与生成预算分离，候选经前缀 KV 复用生成后送入独立验证器服务。这里有一个容易被忽略的数值一致性要求：生成侧的 logits 经过何种精度归一化与采样，验证侧对同一候选的打分必须建立在可比的数值基础上。若生成侧以 FP8 GEMM 加 FP32 累加得到 logits，再以 BF16 做 softmax，而验证器以不同 dtype 重算打分，两者的分数差会被误读为“候选质量差异”，进而扭曲能力估计 $c_i$ 的更新，使预算分配偏向数值噪声而非真实能力边界。</p>\n<p>工程做法是把采样数值路径固定为一条可复现的链路：logits 累加用 FP32，softmax 与温度缩放在 BF16 或 FP32 完成，随机数种子与采样温度在生成与验证两侧共享元数据。前缀 KV 复用段必须记录其量化档位与缩放块边界，验证器在拼接时按同一档位反量化。代价是元数据随 KV 块传递带来的额外带宽与显存开销，但相比采样偏差导致的预算错配，这个开销是可控的。NVFP4 下这一点尤其关键：块缩放因子若未随 KV 块一同复用，验证器重算时的量化网格与生成时不同，分数不可比。</p>\n<p>具体例子：一个边界样本经多次验证，若每次验证的数值路径略有差异，验证预算被消耗在区分噪声上，而非区分候选质量；调度器观察到验证分数方差大，可能误判该样本能力不稳定，进而收缩其预算，与“把算力转移到能力边界样本”的初衷相反。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-18\">十八 · 量化档位缺失下的工程判断</h3>\n<p>论文材料未给出量化方案与硬件档位，因此 NVFP4 下采样稳定性与显存占用无法核验。这留下一个明确的工程缺口：预算函数的收益在调度机制层面可推断（长尾样本受配额约束、验证算力与生成算力分离），但在数值层面无法断言。可核验的是预算区间映射与调度流程；不可核验的是低精度下能力估计 $c_i$ 的信噪比。对部署者的实际含义是：在引入 FP8 或 NVFP4 之前，必须先建立“同一候选在不同 dtype 下打分差”的基线，把这个差值纳入能力估计的置信区间，否则预算分配会把量化误差当成能力差异来放大。</p>\n<p>另一个耦合点是离策略陈旧度：异步流水线在权重同步点对齐版本，超阈值则丢弃过期候选并重排预算。若量化档位在版本间切换（例如新版本启用 NVFP4），旧版本生成的候选与新版本验证器的数值路径不一致，陈旧度判定会被数值差污染。工程上应把 dtype 档位纳入版本对齐的元数据，版本切换时强制重算而非复用 KV。</p>\n<p>具体例子：监控侧记录长尾队列深度与批利用率用于下一轮预算收缩或扩张。若某轮批利用率因 TMEM 分配不均而下降，调度器可能误判为长尾样本过多而收缩困难样本预算；实际原因是量化档位切换导致 kernel 退化。把 dtype 档位与 TMEM 占用写入监控项，才能把吞吐下降归因到正确的层面，而不是让预算函数替 kernel 问题背锅。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-19\">十九 · 能力预算落地的算子边界：配额、前缀复用与数值路径一致性</h3>\n<p>CoBA-RL 的预算函数本身只是调度层的标量映射，真正决定它能否兑现吞吐收益的是算子层能否把“按样本配额”翻译成可执行的批结构。生成侧的核心机制是前缀 KV 复用：同一 prompt 的候选共享已预填的 KV 块，后续 token 只走增量解码，因此预算差异体现在解码步数与验证次数上，而非重复预填。代价是显存侧的碎片化——配额小的样本提前退出批，留下空洞的 KV 块与未对齐的批槽位，调度器必须按配额分组组批才能维持批利用率；若组批粒度过细，单批有效 token 数下降，Tensor Core 的 MMA 利用率随之走低。以边界样本为例，它获得较大生成预算与多次验证，其候选在前缀复用下持续占用 KV 块直至验证回传，这段驻留时间直接抬高显存水位，长尾队列深度监控正是为此设置。</p>\n<p>数值路径一致性是该方案最容易被忽视的失效条件。生成阶段复用前缀 KV 时，若预填与增量解码落在不同精度档位（例如预填走 BF16、解码走 FP8），KV 的数值表示在拼接处产生偏差，采样分布随之漂移；验证器作为独立推理服务若采用不同量化方案，打分与生成侧的候选分布不再同源，预算分配把算力从简单样本转移到边界样本的收益会被采样偏差抵消。材料未给出量化方案与硬件档位，因此 NVFP4 下采样稳定性与显存占用无法核验，工程上只能把“生成与验证共用同一数值路径”作为部署前提而非优化项。累加精度同理：验证器打分若在低精度累加下与生成侧 logits 排序不一致，多次验证配额的意义被削弱。</p>\n<p>异步流水线把这一代价放大。权重同步点做版本对齐，离策略陈旧度超阈值则丢弃过期候选并重排预算，但丢弃意味着已消耗的生成 token 与 KV 驻留全部作废，重排又触发新一轮组批。设样本 $i$ 的候选在版本 $v$ 生成、在版本 $v'$ 被验证，其有效预算可写为</p>\n<div class=\"formula\">$$\\mathcal{B}_{i}^{\\text{eff}}=\\mathcal{B}_{i}\\cdot\\mathbb{1}\\!\\left[\\Delta v\\le \\Delta v_{\\max}\\right]-\\lambda\\,D_{\\text{stale},i}$$</div>\n<p>其中 $\\Delta v$ 为版本跨度，$D_{\\text{stale},i}$ 为该样本的陈旧度度量，$\\lambda$ 为惩罚系数；材料未给出具体阈值，故该项只能定性判断：同步频率过低会系统性压低有效预算，使边界样本的实际验证次数低于配额名义值。长尾配额过紧则欠采样困难样本，过松则失去吞吐收益，阈值 $\\tau$ 与温度 $T$ 必须与 SLO 联合调参，而非独立设定。冷启动阶段能力估计未更新，预算分配偏向均匀配额，此时前缀复用与组批退化为统一预算形态，方案的结构性优势尚未生效。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>算子层表现</th><th>系统代价</th></tr></thead><tbody><tr><td>预填与解码精度档位不一致</td><td>KV 拼接处数值漂移</td><td>采样偏差抵消预算收益</td></tr><tr><td>验证器量化方案与生成侧不同源</td><td>打分排序与 logits 不一致</td><td>多次验证配额失效</td></tr><tr><td>配额分组过细</td><td>批槽位空洞、MMA 利用率下降</td><td>吞吐下降、显存碎片上升</td></tr><tr><td>权重同步频率过低</td><td>候选丢弃与预算重排</td><td>已耗 token 与 KV 驻留作废</td></tr></tbody></table>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-20\">二十 · 显存账本的三个账户与预算函数的耦合</h3>\n<p>在 rollout 与训练解耦的部署形态下，单张 B200 的 HBM3e 容量要同时容纳三类常驻对象：权重、激活（含临时 workspace 与通信缓冲）、KV cache。三者不是静态切分，而是随批内样本的生成预算动态伸缩。CoBA-RL 的预算函数 $\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min})\\cdot\\sigma((c_{i}-\\tau)/T)$ 直接决定了 KV 账户的瞬时占用：一个样本的生成 token 配额就是它的 KV 长度上界，批内所有样本的配额之和乘以每 token 的 KV 字节数，构成该批的 KV 峰值需求。工程上必须把这个峰值与权重常驻量、激活峰值一起放进同一张账本，否则调度器按配额组批时会在长尾样本上撞到 OOM 边界。</p>\n<p>可复算的账本形式是：设权重占用 $W$ 字节（与并行拓扑和量化方案绑定），激活峰值 $A$（随批大小与序列长度增长），KV 峰值 $K=\\sum_{i\\in \\text{batch}} \\mathcal{B}_{i}\\cdot k_{t}$，其中 $k_{t}$ 为每 token 每层的 KV 字节数。约束为 $W+A+K\\le \\alpha C_{\\text{HBM}}$，$\\alpha$ 是留给碎片与临时分配的余量系数。注意这里 $\\mathcal{B}_{i}$ 是 token 配额而非字节，$k_{t}$ 由层数、KV 头数、头维度与 KV 精度共同决定——量化方案材料未给出，因此 $k_{t}$ 只能按定性档位讨论，不能代入具体数字。这个约束的工程含义是：预算函数的上界 $\\mathcal{B}_{\\max}$ 不是自由参数，它被 KV 账户的剩余容量反向钳制；把 $\\mathcal{B}_{\\max}$ 调大以照顾能力边界样本，等价于压缩同批可容纳的样本数，吞吐与长尾公平性在此处直接对冲。</p>\n<p>一个具体例子：批内 64 个样本，若多数简单样本配额很小、少数边界样本配额接近 $\\mathcal{B}_{\\max}$，则 KV 峰值由少数样本主导，批利用率被拉低；调度器若按平均配额估算容量，实际峰值会超出预估，触发抢占或重排。这正是长尾样本独占批资源的显存侧表现，与调度层的配额队列是同一问题的两个面。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-21\">二十一 · 分页与 KV 复用的字节级代价</h3>\n<p>分页 KV cache 把逻辑序列切成固定大小的 block，按需分配物理页，消除连续序列长度带来的外部碎片。对 CoBA-RL 而言，分页的价值在于让 $\\mathcal{B}_{i}$ 的差异不转化为显存浪费：小配额样本只占少量页，大配额样本按增长逐页追加，批内不同预算的样本可以共存而不需要按最大配额预留。代价是页表间接寻址带来的额外元数据与访存跳转，以及页粒度与注意力 kernel 的 tile 形状不匹配时的利用率损失。页大小选得粗，碎片少但小配额样本浪费页内空间；选得细，元数据开销与 TLB 压力上升。这个权衡在长尾比例高的负载下尤其敏感。</p>\n<p>前缀 KV 复用是第二个杠杆。同一 prompt 的多次采样、以及验证器对同一候选的重复打分，都可以复用已预填的 KV 页，避免重复预填的算力与带宽。复用命中时省下的是预填阶段的 HBM 读写与 MMA 计算；未命中时退化为常规预填。复用率直接进入吞吐账本：设批内总预填 token 数为 $P$、命中复用比例为 $h$，则实际预填代价约为 $(1-h)P$ 的算力加页表查找开销。CoBA-RL 的验证预算按样本分配，意味着边界样本会被多次验证，若验证器与生成器共享前缀 KV，则这部分重复预填可被摊薄；若两者是独立推理服务、KV 不共享，则验证侧的预填代价独立计入，验证算力与生成算力分离的部署选择在此处产生显存与带宽的重复开销。</p>\n<p>压缩是第三个杠杆。KV 量化的字节收益是线性的：每 token KV 从 BF16 降到 FP8 近似减半，降到 NVFP4 再减半，但采样数值路径与验证器的一致性成为风险点——材料明确指出若 NVFP4 下采样数值路径与验证器不一致，预算分配收益可能被采样偏差抵消。因此压缩不能只看字节账本，还要看数值账本：生成侧与验证侧必须走同一数值路径，否则预算函数省下的显存换来的是打分偏差。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-22\">二十二 · 卸载与带宽瓶颈的定位</h3>\n<p>卸载（offload）把冷 KV 页或非活跃权重搬到主机内存或远端池，用 PCIe/NVLink 带宽换 HBM 容量。判断是否值得卸载，要看被搬对象的访问频率与搬移字节的比值：长尾样本的 KV 在生成过程中持续被注意力读取，卸载它会引入反复的往返搬移，带宽代价高于容量收益；相反，已完成生成、等待验证的候选 KV 是冷数据，卸载到主机侧再取回是合理的。CoBA-RL 的异步流水线在权重同步点做版本对齐，过期候选被丢弃并重排预算，这些被丢弃候选的 KV 应立即释放而非卸载，否则会挤占页池。</p>\n<p>带宽瓶颈的位置需要分阶段判断。预填阶段是计算密集但受 HBM 带宽约束的混合体，KV 写入与权重读取同时发生；解码阶段每步只处理一个 token，权重读取量远大于 KV 读取量，是典型的带宽受限阶段，批大小决定了权重读取能否被摊薄。分页与复用降低的是预填与 KV 写入侧的带宽压力，而解码侧的带宽瓶颈只能靠增大批内并发或提高权重读取效率来缓解。CoBA-RL 把简单样本快速通过验证、把边界样本留在生成阶段，实际上是在调整批内处于解码阶段的样本数——边界样本多则解码并发高、权重读取摊薄好，但 KV 峰值与长尾等待同时上升。</p>\n<p>一个具体机制层面的例子：调度器读取能力估计后按预算组批，若把大量小配额样本与少量大配额样本混批，解码阶段的权重读取被小样本摊薄，但大配额样本的 KV 页持续增长，页池在批末接近耗尽；若按配额分层组批，同类样本的 KV 增长曲线一致，页池峰值可预测，代价是批内样本数下降、权重读取摊薄变差。这个分层决策就是带宽与显存的直接交换。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-23\">二十三 · 一个可复算的显存预算流程</h3>\n<p>下面给出不依赖具体硬件数字的复算流程，读者可代入自己档位的容量与带宽参数。第一步，确定每 token KV 字节 $k_{t}=2\\cdot L\\cdot H_{kv}\\cdot d_{h}\\cdot b_{kv}$，其中 $L$ 为层数、$H_{kv}$ 为 KV 头数、$d_{h}$ 为头维度、$b_{kv}$ 为每元素字节数（GQA/MQA 下 $H_{kv}$ 小于注意力头数，这是容量账本里最有效的杠杆之一）。第二步，按预算函数算出批内各样本配额 $\\mathcal{B}_{i}$，求和得 KV 峰值 $K$。第三步，扣除权重常驻 $W$ 与激活峰值 $A$，检查 $W+A+K\\le \\alpha C_{\\text{HBM}}$。第四步，若超限，优先收缩 $\\mathcal{B}_{\\max}$ 或把长尾样本移入受限配额队列，而不是压缩 $\\mathcal{B}_{\\min}$——后者会让简单样本无法完成生成，破坏验证通过率。</p>\n<div class=\"formula\">$$K=\\sum_{i\\in\\text{batch}}\\left[\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)\\right]\\cdot k_{t}$$</div>\n<p>第五步，估算页池需求：$N_{\\text{page}}=\\lceil K/p_{\\text{page}}\\rceil$ 加上复用命中带来的共享页与页表元数据，页池容量应留出长尾队列深度对应的余量，因为受限配额队列中的样本在等待期间仍持有已分配的页。第六步，把带宽账本叠加：预填阶段的有效带宽需求约为 $(1-h)P$ 的 KV 写入加权重读取，解码阶段为每步权重读取除以批内解码样本数。两个阶段的峰值不同时出现，容量规划取二者较大者对应的并发上限。</p>\n<p>一个可核验的工程判断：材料未给出硬件档位与量化方案，因此上述流程只能给出结构而非数值结论；但结构本身已经说明，CoBA-RL 的预算分配在显存侧等价于对 $K$ 的动态整形，长尾配额队列是把 $K$ 的尾部截断以保护批利用率，而 $\\mathcal{B}_{\\max}$ 的上调必须以页池余量为前提。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-24\">二十四 · 长尾队列、离策略陈旧度与显存回收的联动</h3>\n<p>长尾样本被限制在受限配额队列内，避免单个超长样本占满批导致整批等待。从显存角度看，这个队列是双刃剑：队列中的样本持有已分配的 KV 页却不参与当前批的解码，等于用容量换吞吐稳定性。队列深度监控因此必须与页池余量联合看——队列过深时，页池被冷 KV 占据，新批无法组起；队列过浅时，长尾样本反复进出批，预填与复用命中率下降。CoBA-RL 监控侧记录长尾队列深度与批利用率，用于下一轮预算收缩或扩张，这个反馈回路实际上是在调页池的周转率。</p>\n<p>异步流水线的权重同步点引入第二个联动：离策略陈旧度超阈值则丢弃过期候选并重排预算。被丢弃候选的 KV 必须立即回收进页池，否则陈旧数据占用容量、挤压新批。材料未给出具体阈值与权重同步频率，因此无法量化丢弃率对页池周转的影响；可判断的是，同步频率越低，单次丢弃的候选越多，页池的瞬时回收压力越集中，预算重排需要在版本对齐的同一时刻完成，避免回收与重排在时间上错位造成页池抖动。</p>\n<p>失败模式在此处具体化：长尾配额过紧会欠采样困难样本，过松则失去吞吐收益，阈值需与 SLO 联合调参；而配额松紧同时改变 KV 峰值与页池周转，SLO 调参不能只看调度层的队列指标，必须把显存回收速率纳入同一控制回路。冷启动阶段能力估计未更新、预算偏向均匀配额，此时 KV 峰值分布最宽，页池应按均匀配额的最坏情况预留，待能力估计收敛后再收缩。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-25\">二十五 · 验证侧显存与生成侧显存的分离账</h3>\n<p>奖励模型与验证器作为独立推理服务接收候选并回传分数，验证预算按样本分配。这意味着验证侧有自己的权重常驻与 KV 账本：验证器对候选做前向打分时，候选 token 的 KV 需要重新预填（除非与生成侧共享前缀 KV），验证批的显存峰值由验证预算决定的候选数乘以候选长度决定。生成侧与验证侧的显存不能简单相加为一张卡的容量，因为它们是解耦部署，可能落在不同卡或不同池上；但若共卡部署，则两侧峰值可能在同一时刻叠加——生成侧在解码、验证侧在预填，带宽争用与容量争用同时发生。</p>\n<p>工程判断落在配额与页池的联合设计上：验证预算大的边界样本会同时抬高生成侧 KV（长生成）与验证侧 KV（多次打分），两侧的容量需求正相关，因此按能力估计分层组批时，应把高验证预算样本的验证请求错峰送入验证服务，避免生成峰值与验证峰值重合。验证算力与生成算力分离的收益在于两侧可以独立扩缩容，代价是前缀 KV 不共享带来的重复预填；是否共享取决于复用命中率 $h$ 与跨服务 KV 传输的带宽代价，材料未给出该配置，只能作为部署时的显式取舍项记录在账本上。</p>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-26\">二十六 · 连续批处理与预算配额组批</h3>\n<p>CoBA-RL 的调度器不是先到先组批，而是先读能力估计再组批。每个样本在进入 rollout 引擎时携带一个能力估计 $c_i$，预算函数把它映射成生成 token 配额 $\\mathcal{B}_i$，调度器按配额分档组批：小配额样本聚成高并发短批，大配额样本聚成低并发长批。这一改动直接改变了连续批处理（continuous batching）的迭代节奏——传统做法是每个 decode step 扫全部在批序列，批内最长序列决定单步开销；按配额分档后，短批的 step 间隔被压到与短样本长度同阶，长批则在独立队列里推进，互不拖累。代价是批利用率下降：分档越细，每档能凑满的并发越少，SM 占用率越难打满。工程判断是档位数取 3–4 档、档内按到达顺序填充，档间共享同一组 KV 块池，用块级回收而非序列级回收来弥补碎片。</p>\n<p>伪代码层面，组批循环可写成：读 $c_i$ → 算 $\\mathcal{B}_i$ → 按 $\\mathcal{B}_i$ 落档 → 档内凑批至并发上限或超时 → 发批。超时参数是吞吐与尾延迟的直接旋钮：超时短则批小、延迟低、吞吐低；超时长则批满、吞吐高、短样本被长样本拖住。CoBA-RL 把超时按档设置，小配额档超时短，大配额档超时长，等于承认长样本本来就慢，不让它污染短样本的尾延迟。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-27\">二十七 · Chunked prefill 与前缀 KV 复用的耦合</h3>\n<p>chunked prefill 把长 prompt 的预填切成固定大小的块，与 decode 交错执行，避免一个超长预填独占整个 step。CoBA-RL 的预算分配在这里多了一层含义：生成预算大的样本往往 prompt 也长，其预填块数多，若与 decode 同批交错，会周期性拉高单步时延。做法是把大配额样本的预填块调度到低优先级流，短样本的预填与 decode 优先占用 step 预算。前缀 KV 复用则进一步削减预填总量——同一 prompt 前缀在多次采样或多次验证间共享 KV，重复预填代价被摊薄。代价在显存：前缀块被多序列引用时不能立即回收，KV 块池的驻留压力上升，块分配器的引用计数与驱逐策略成为瓶颈。一个具体例子是同一道数学题的多次采样共享题干前缀，若前缀块被 8 条候选引用，则这 8 条候选的 decode 各自追加 KV，而前缀部分只算一次预填。</p>\n<div class=\"formula\">$$\\text{step 预算} = \\sum_{j \\in \\text{decode}} 1 + \\sum_{k \\in \\text{prefill}} \\lceil L_k / C \\rceil \\le \\text{上限}$$</div>\n<p>其中 $C$ 为 chunk 大小，$L_k$ 为待预填长度。这个约束决定了每 step 能塞进多少预填块，也就决定了长 prompt 样本的排队深度。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-28\">二十八 · 优先级、抢占与长尾配额队列</h3>\n<p>长尾样本是吞吐杀手：单个超长生成占满批，整批等待它结束。CoBA-RL 的应对是把长尾样本关进受限配额队列，队列有并发上限与 token 配额上限，超出即排队而非抢占主批资源。抢占机制在 KV 层面表现为块驱逐：当显存紧张时，低优先级序列的 KV 块被换出到主机侧或直接丢弃重算，重算代价是二次预填。工程上要区分两种抢占——换出（swap）保留进度但吃 PCIe 带宽，重算（recompute）省显存但吃算力。对长尾样本，重算往往更划算，因为其 KV 体积大、换出带宽开销高。代价是尾延迟的方差：被抢占的序列恢复时间不确定，SLO 若按 P99 考核，抢占次数必须计入预算。</p>\n<p>优先级不是静态的。能力估计随采样结果更新，边界样本的预算可能在一轮内扩张，调度器需支持档位迁移；迁移时已分配的 KV 块要重新计价，否则块池会出现“高配额序列占着低配额块”的错配。监控侧记录的长尾队列深度就是这一迁移压力的直接指标：深度持续上升说明配额过紧，困难样本被欠采样；深度长期为零说明配额过松，吞吐收益被浪费。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-29\">二十九 · 分离式预填/解码与验证服务的独立推理</h3>\n<p>CoBA-RL 把奖励模型与验证器做成独立推理服务，候选生成完才送入打分，生成算力与验证算力在物理上分离。这与分离式预填/解码（disaggregated prefill/decode）同构：预填是算力密集、解码是带宽密集，两者混跑会互相压制；生成与验证同理，生成侧吃 KV 带宽与 decode 吞吐，验证侧吃预填算力与短序列打分。分离后各自按最优批型调度，验证服务可以批量收候选、按验证预算决定打分次数。代价是两次网络往返与候选驻留：候选 token 要在生成侧保留到验证回传，KV 或文本需跨服务传输，传输量随候选长度线性增长。工程判断是验证服务按批收单、设最大等待窗口，窗口内凑不满则降批发送，用吞吐换尾延迟。</p>\n<p>验证预算按样本分配意味着验证服务收到的请求异构：简单样本一次打分即过，边界样本多次打分。服务侧需支持同批内不同打分次数的调度，否则多次打分的样本会拖住单次样本。做法是把多次打分拆成多轮短批，轮间让出 step 给其他请求，这与 chunked prefill 的交错思路一致。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-30\">三十 · 时延与吞吐的取舍，尾延迟怎么压</h3>\n<p>时延与吞吐的取舍在 CoBA-RL 里被预算函数显式化：$\\mathcal{B}_i$ 大则单样本时延长、批吞吐低；$\\mathcal{B}_i$ 小则相反。整体吞吐近似为各档吞吐按样本比例加权，尾延迟则由最长配额档与抢占次数决定。压尾延迟的三个杠杆：其一，按档设超时，短档不等长档；其二，长尾队列设硬并发上限，超限即排队，不让长样本进入主批；其三，权重同步点做版本对齐，离策略陈旧度超阈值即丢弃过期候选并重排预算——丢弃本身是尾延迟的负项（浪费算力），但不丢弃会让陈旧候选污染训练信号，取舍点在于丢弃率与陈旧度的乘积是否超过重算成本。材料未给出具体阈值，工程上只能按监控项联动调参：长尾队列深度上升则收缩困难样本预算，批利用率下降则扩张。</p>\n<table class=\"mini\"><thead><tr><th>杠杆</th><th>作用对象</th><th>代价</th></tr></thead><tbody><tr><td>按档超时</td><td>组批等待</td><td>短档批小、吞吐降</td></tr><tr><td>长尾硬并发上限</td><td>批资源占用</td><td>困难样本排队、欠采样</td></tr><tr><td>版本对齐丢弃</td><td>离策略陈旧度</td><td>算力浪费、重排开销</td></tr><tr><td>前缀 KV 复用</td><td>重复预填</td><td>块池驻留、驱逐压力</td></tr></tbody></table>\n<p>一个具体例子：一批 64 条候选，其中 4 条为长尾，若不加限制，这 4 条会把批的 step 间隔拉到最长序列的量级，其余 60 条的完成时间被整体推迟；加配额队列后，60 条在短档快速完成并释放 KV，4 条在独立队列慢跑，整批的 P99 由短档决定而非长尾决定。代价是那 4 条的采样次数被配额压缩，能力边界样本的覆盖率下降，需在下一轮预算扩张时补回。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-31\">三十一 · 异步流水线与调度层的联动</h3>\n<p>rollout 与训练解耦后，调度器面对的是异步到达的权重版本：生成侧用旧权重产候选，训练侧用新权重更新，版本差即离策略陈旧度。调度层的预算重排必须与版本对齐联动——权重同步点到达时，未完成的候选按陈旧度分级，超阈值者丢弃，未超者继续但预算冻结，避免用旧权重生成的候选占用新预算。监控项里长尾队列深度与批利用率要同时看：队列深而利用率低，说明配额与并发不匹配；队列浅而利用率低，说明档位分得太细。这两个指标的联合读数比单看吞吐更能定位调度瓶颈。材料未给出硬件档位与量化方案，NVFP4 下采样数值路径与验证器是否一致无法核验，若不一致，预算分配的收益会被采样偏差抵消，调度层再精细也补不回来。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-32\">三十二 · 配额队列的边界：能力预算在调度层的失效条件与代价</h3>\n<p>把能力预算落到批调度层，最直接的机制是<strong>受限配额队列</strong>：调度器按预算函数 $\\mathcal{B}_i$ 为每个样本算出生成 token 配额与验证次数配额，再按配额分组组批；长尾样本不进入主批，而是被压进一个受配额约束的旁路队列，只有主批出现空槽时才被拉入。这样做的代价是显式的——旁路队列里的样本等待时间被拉长，批利用率在主批尾部出现凹陷。设主批容量为 $C$、长尾队列长度为 $L$、单样本平均生成 token 为 $\\bar{t}$，则批利用率可近似写成</p>\n<div class=\"formula\">$$\\eta \\approx \\frac{\\sum_{i\\in \\text{batch}} \\mathcal{B}_i}{C\\cdot \\bar{t}}\\cdot\\frac{1}{1+L/C}$$</div>\n<p>分子是配额之和而非实际消耗，分母里的 $L/C$ 项说明长尾队列一旦积压，利用率按队列深度线性衰减。这就是该方案在吞吐侧的硬边界：配额越紧，$\\eta$ 越稳，但困难样本被欠采样；配额越松，长尾重新挤占主批，整批等待时间回升。阈值 $\\tau$ 与温度 $T$ 不是纯统计参数，它们必须与 SLO 联合调参——$T$ 偏小会让预算映射接近阶跃，边界样本配额突增，批内 token 长度方差变大，组批效率下降；$T$ 偏大则预算趋于均匀，能力导向退化为统一预算，方案失去意义。</p>\n<p>第二个失效条件在验证侧。生成预算与验证预算分离后，奖励模型与验证器是独立推理服务，候选经前缀 KV 复用生成后送入打分。验证次数配额按样本分配，意味着边界样本会占用更多验证槽位；当验证服务自身接近饱和时，验证队列的排队延迟会反向传导到 rollout 侧，使调度器误判样本“已完成”，实际是候选卡在验证队列里。此时长尾队列深度监控会失真——它只统计生成侧排队，不统计验证侧积压。工程上必须把两侧队列深度合并成一个端到端指标，否则预算收缩/扩张的反馈回路会震荡：生成侧收缩、验证侧积压未缓解，下一轮又扩张，形成周期性过冲。</p>\n<p>第三个边界是异步流水线的版本对齐。权重同步点做版本检查，离策略陈旧度超阈值则丢弃过期候选并重排预算。这里的系统代价是<strong>丢弃即浪费</strong>：一个已经消耗了较大生成预算的边界样本，若在同步点被判过期，其全部 token 与验证槽位作废，预算重排后还要重新排队。同步频率越低，单次丢弃的期望浪费越大；同步频率越高，rollout 引擎的有效吞吐被同步屏障切碎。材料未给出具体阈值与同步频率，因此无法定量评估这一偏差，但机制上可以确定：陈旧度阈值必须与配额队列深度联动——队列越深，越应缩短同步间隔，否则长尾样本在队列中等待期间跨越多个权重版本的概率上升。冷启动阶段能力估计未收敛，预算分配偏向均匀配额，此时配额队列退化为普通批调度，方案的全部收益都压在能力估计的更新速度上；材料未说明更新方式，这是该方案在部署初期最脆弱的环节。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发机制</th><th>系统代价</th></tr></thead><tbody><tr><td>配额过紧</td><td>长尾样本被压入旁路队列，主批空槽才拉入</td><td>困难样本欠采样，批利用率随 $L/C$ 衰减</td></tr><tr><td>验证服务饱和</td><td>验证槽位排队反向传导，生成侧误判完成</td><td>端到端延迟被低估，反馈回路震荡</td></tr><tr><td>同步间隔过长</td><td>长尾样本跨版本，候选被判过期丢弃</td><td>已消耗生成与验证预算作废，需重排重排队</td></tr><tr><td>冷启动估计未收敛</td><td>预算映射趋于均匀，配额队列退化</td><td>能力导向收益归零，退化为统一预算调度</td></tr></tbody></table>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-33\">三十三 · 并行拓扑：把 CoBA-RL 的预算落到切分维度上</h3>\n<p>CoBA-RL 的预算函数只回答“每个样本给多少 token 与多少次验证”，它不回答“这些 token 在哪些 GPU 上生成”。在 Blackwell 部署里，后者由并行拓扑决定：张量并行（TP）切分单层权重与注意力头，专家并行（EP）切分 MoE 专家，流水并行（PP）切分层，数据并行（DP）复制整模型并各自持有不同的 rollout 请求。CoBA-RL 的预算分配天然与 DP 对齐——每个 DP rank 持有独立的批，调度器按能力估计给该批内样本分配生成配额，因此“简单样本小配额、边界样本大配额”在 DP 维度上是局部的，不需要跨 rank 协商。真正需要跨 rank 的是 TP/EP 组内的集合通信：一次前向里每个 token 的 hidden state 都要在 TP 组内做 All-Reduce，在 EP 组内做 All-to-All 把 token 路由到专家所在 rank。</p>\n<p>代价可以直接写成通信量与预算的关系。设某 DP rank 的批内 token 总数为 $S=\\sum_i \\mathcal{B}_i$，TP 度为 $t$，单层 hidden 维度 $h$、字节宽 $b$，则每层 All-Reduce 的通信量近似为</p>\n<div class=\"formula\">$$V_{\\text{AR}} \\approx 2\\cdot\\frac{t-1}{t}\\cdot S\\cdot h\\cdot b$$</div>\n<p>预算函数把 $S$ 抬高时，通信量线性上升；而 All-Reduce 的时延并不随 $S$ 线性下降，因为小消息受固定启动开销支配。这就是 CoBA-RL 在 TP 组内遇到的第一个工程矛盾：边界样本获得大生成预算，使 $S$ 变大、单次 All-Reduce 更“划算”，但长尾样本被配额队列限制后，批内 $S$ 的方差变大，调度器组出的批可能忽大忽小，集合通信的有效带宽利用率随之抖动。工程判断是：预算分配应在组批阶段与 TP 组的消息尺寸对齐，而不是先组批再让 NCCL 去适应任意尺寸。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-34\">三十四 · NVLink 5 与 NVSwitch：All-to-All 是 EP 的真实成本</h3>\n<p>GB200/GB300 NVL72 机柜内以 NVLink 5 与 NVSwitch 构成全互联域，EP 组内的 All-to-All 因此可以落在单机柜域内而不出 InfiniBand。对 CoBA-RL 而言，这一点直接改变验证服务的部署选择：奖励模型与验证器作为独立推理服务，如果与 rollout 引擎同处一个 NVLink 域，候选 token 的传输走 NIXL 的点对点路径，不必经过主机内存与网卡；如果跨域，则每次验证回传都变成一次网络往返，验证预算越大、往返次数越多。</p>\n<p>All-to-All 的代价可用每个 token 的路由字节数估算。设 EP 度为 $e$、每 token 经 $k$ 个专家、专家中间维度 $h_e$，则一次 MoE 层的 All-to-All 发送量为 $S\\cdot k\\cdot h_e\\cdot b$，且是每个 rank 都要发出的量。当 CoBA-RL 给边界样本分配大生成预算时，这些样本的 token 在 EP 组内产生的 All-to-All 流量按比例放大；而简单样本的小配额几乎不贡献流量。于是 EP 组的通信瓶颈不是由平均预算决定，而是由批内最大配额样本的数量决定——这正是长尾配额队列要压制的东西。把长尾样本限制在受限配额队列内，除了避免整批等待，还顺带压住了 EP All-to-All 的峰值。</p>\n<p>具体例子：一个批内 64 个样本，多数样本配额接近 $\\mathcal{B}_{\\min}$，少数边界样本接近 $\\mathcal{B}_{\\max}$。若不加配额约束，单个超长样本可能占据批内多数 token，使 EP 组每层 All-to-All 的有效载荷被它主导，其余样本的专家计算被迫等待这次大传输完成。配额队列把该样本的 token 数封顶后，批内 token 分布变窄，All-to-All 的消息尺寸更接近，流水线的气泡减少。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-35\">三十五 · NIXL 传输：验证服务解耦后的数据面</h3>\n<p>CoBA-RL 把验证算力与生成算力分离，候选经前缀 KV 复用生成后送入独立验证器服务打分。这条路径的数据面由 NIXL 承担：它把候选 token、对应的 KV 块与元数据从 rollout 引擎的显存/内存直接传到验证服务的缓冲区，避免一次主机中转。传输代价取决于候选长度与验证预算：验证预算为 $v_i$ 次时，同一候选可能被多次送入验证器（例如多次采样打分或分阶段筛选），传输量近似为 $v_i\\cdot L_i\\cdot b$，其中 $L_i$ 是候选 token 数。</p>\n<p>这里出现一个容易被忽略的耦合：前缀 KV 复用降低了生成侧重复预填，但也意味着验证服务收到的候选共享大量前缀。如果 NIXL 传输按整段候选搬运而不做前缀去重，验证侧会重复接收相同前缀，浪费 NVLink 带宽与验证服务的显存。工程上的做法是让验证服务按前缀哈希索引已缓存的 KV 块，只传输新增后缀；这与生成侧的前缀共享是同一套块管理，只是消费方从 rollout 引擎换成了验证器。代价是验证服务需要维护自己的 KV 块表，显存占用随并发候选数上升，在 NVL72 的单柜显存预算内需要与生成侧的 KV cache 争抢。</p>\n<p>另一个代价是版本对齐。异步流水线在权重同步点检查版本，若离策略陈旧度超阈值则丢弃过期候选并重排预算。被丢弃的候选已经消耗了生成算力与 NIXL 传输带宽，这部分是纯损失。权重同步越频繁，丢弃越少但同步本身打断流水线；同步越稀疏，丢弃越多。CoBA-RL 的材料未给出阈值，但机制上可以判断：预算重排必须与版本对齐联动，否则大预算样本在旧权重下生成的长候选更容易整体作废。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-36\">三十六 · 通信何时成为瓶颈：三个可判定的信号</h3>\n<p>不是所有部署里通信都是瓶颈。对 CoBA-RL 的调度器而言，有三个可观测信号可以用来判定是否已进入通信受限区间。第一，批内 token 总数 $S$ 的方差相对均值偏大，说明组批被少数大配额样本主导，TP 组内 All-Reduce 的消息尺寸不一致，NCCL 难以进入带宽饱和区。第二，EP 组内 All-to-All 的等待时间占单层前向时间的比例上升，且与批内最大配额样本的 token 数正相关——这说明长尾配额没有压住峰值。第三，验证服务的 NIXL 入站带宽接近 NVLink 域上限，而验证队列深度同时上升，说明验证预算 $v_i$ 的分配超过了验证服务的消费能力，传输在排队。</p>\n<p>定量地，可以把单次迭代的时间写成计算与通信的较大者：</p>\n<div class=\"formula\">$$T_{\\text{iter}} \\approx \\max\\left(\\frac{F}{P_{\\text{comp}}},\\ \\frac{V_{\\text{AR}}+V_{\\text{A2A}}+V_{\\text{NIXL}}}{B_{\\text{NVLink}}}\\right)$$</div>\n<p>其中 $F$ 是本批的浮点工作量，$P_{\\text{comp}}$ 是有效算力，$B_{\\text{NVLink}}$ 是域内有效带宽。当第二项超过第一项，预算分配再多也换不来吞吐，此时正确的动作是收缩 $\\mathcal{B}_{\\max}$ 或收紧长尾配额，把批内 token 分布压窄，让通信项回落。反过来，若第一项主导，说明算力仍是瓶颈，可以把预算向边界样本扩张。CoBA-RL 的监控侧记录长尾队列深度与批利用率，正是为这个判断提供输入：批利用率下降而队列深度上升，通常意味着通信项已经压过计算项。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-37\">三十七 · 切分选择与预算函数的联合调参</h3>\n<p>TP、EP、PP、DP 的选择不是独立的。TP 度越大，单卡权重越小但 All-Reduce 越多；EP 度越大，专家越分散但 All-to-All 越重；PP 度越大，单卡层数越少但流水气泡越多；DP 度越大，批越分散、预算分配的局部性越好但权重同步的副本越多。对 CoBA-RL 这种 rollout 与训练解耦的形态，DP 是天然的预算分配单元，TP/EP 是通信成本的来源，PP 则影响权重同步点的粒度。</p>\n<p>一个具体的工程判断：当模型是 MoE 且 EP 组跨多个 NVLink 域时，All-to-All 会成为主导通信项，此时应优先收紧长尾配额、压低批内最大 token 数，而不是提高 TP 度——提高 TP 度只会增加 All-Reduce 而不会减少 All-to-All。当模型是稠密模型且 TP 组在单柜内时，All-Reduce 落在 NVSwitch 域内，通信项通常让位于计算项，预算可以向 $\\mathcal{B}_{\\max}$ 扩张。表格给出切分维度与 CoBA-RL 预算动作的对应关系：</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>主要通信</th><th>受预算影响的量</th><th>预算侧动作</th></tr></thead><tbody><tr><td>TP</td><td>All-Reduce</td><td>批内 token 总数 $S$</td><td>组批时对齐消息尺寸，压方差</td></tr><tr><td>EP</td><td>All-to-All</td><td>批内最大配额样本 token 数</td><td>收紧长尾配额，压峰值</td></tr><tr><td>PP</td><td>点对点激活</td><td>流水气泡与同步点粒度</td><td>预算重排与版本对齐联动</td></tr><tr><td>DP</td><td>权重同步、NIXL 回传</td><td>各 rank 批内 $S$ 分布</td><td>按 rank 局部执行预算函数</td></tr></tbody></table>\n<p>这张表的用法不是查表配置，而是定位瓶颈后决定预算往哪边调。CoBA-RL 的材料未给出并行拓扑，因此无法判定其默认部署落在哪一列；但机制上可以确定，预算函数若只在调度层执行而不与切分维度对齐，长尾配额压住的是批等待，未必压住 EP 的 All-to-All 峰值。真正把吞吐做稳的做法，是让配额队列的上限与 EP 组内可接受的最大消息尺寸挂钩，让 $\\mathcal{B}_{\\max}$ 的扩张受 $T_{\\text{iter}}$ 中通信项的约束，而不是只受 SLO 约束。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-38\">三十八 · 预算分配落进并行拓扑之后的通信账</h3>\n<p>能力预算一旦落到多卡部署，生成配额就不再只是调度器里的一个数，而是决定了每个 batch 在 TP/EP/PP/DP 四个维度上的切分形状。CoBA-RL 的预算函数 $\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min})\\cdot\\sigma((c_{i}-\\tau)/T)$ 输出的是逐样本 token 配额，但组批时真正决定通信量的是批内配额分布的方差：边界样本配额大、简单样本配额小，同一批内序列长度差异被放大，TP 组内每层 All-Reduce 的参与张量尺寸随最长序列走，短样本被迫陪跑。工程上更稳的做法是按配额分档组批，把 $\\mathcal{B}_{i}$ 落在同一区间带的样本聚成一批，用批内长度齐整换取 All-Reduce 的有效载荷收敛；代价是队列等待时间上升，长尾受限配额队列的深度监控项正是为此设的。EP 场景下 MoE 层的 All-to-All 更敏感：token 被路由到不同专家所在卡，配额大的样本产生更多 token，路由不均衡直接放大 All-to-All 的尾延迟，NVLink 5 与 NVSwitch 的全互联带宽再高也挡不住单卡出口拥塞。</p>\n<p>把通信代价写成可判断的形式：单次 TP All-Reduce 的有效载荷近似正比于 $b\\cdot s\\cdot h$（批大小、序列长度、隐维），而每 token 的计算量正比于 $b\\cdot s\\cdot h^{2}$，因此计算通信比约为 $h$ 量级——这意味着 TP 度越大，单卡分到的 $h$ 越小，通信占比越高。CoBA-RL 的预算分配把 $s$ 的分布拉宽，等价于把这一比值的最坏情况压低，长尾样本是通信瓶颈的主要贡献者。PP 的流水气泡与配额方差叠加：阶段间激活传输量随 micro-batch 的 $s$ 走，边界样本的大配额会让某个 stage 成为拖尾 stage，整条流水等它。DP 侧梯度或权重同步走 All-Reduce，异步流水线的权重同步点若与预算重排同拍，版本对齐的通信峰值会和长尾队列的突发叠在一起。</p>\n<p>NIXL 在这里的角色是解耦传输：rollout 引擎与训练侧、验证器服务之间的 KV 与前缀缓存搬运不经过集合通信，而是点对点按需拉取。前缀共享命中时省掉重复预填，但跨节点拉取 KV 的带宽开销与配额成正比——边界样本复用长前缀，单次传输量大，若 NIXL 路径与 NVLink 域不重合，跨域流量会成为隐性瓶颈。验证器作为独立推理服务接收候选，验证预算按样本分配，验证侧 All-Reduce 规模小但请求数多，QPS 型瓶颈而非带宽型瓶颈。判断通信何时成为瓶颈的工程准则：当单批内配额方差超过阈值、或 EP 路由不均衡度上升、或长尾队列深度持续高于批利用率可吸收的水平时，预算分配的吞吐收益会被通信尾延迟吃掉；此时应收缩困难样本配额或改分档组批，而不是加大 TP 度。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>通信形态</th><th>被预算方差放大的量</th><th>代价落点</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>批内最长序列 $s_{\\max}$</td><td>单卡出口带宽、层间延迟</td></tr><tr><td>EP</td><td>All-to-All</td><td>路由 token 数与不均衡度</td><td>尾延迟、单卡拥塞</td></tr><tr><td>PP</td><td>阶段间激活传输</td><td>micro-batch 长度方差</td><td>流水气泡、拖尾 stage</td></tr><tr><td>DP</td><td>权重/梯度 All-Reduce</td><td>同步点与预算重排同拍</td><td>版本对齐峰值</td></tr><tr><td>NIXL</td><td>点对点 KV 拉取</td><td>前缀复用长度</td><td>跨域带宽、预填节省被抵消</td></tr></tbody></table>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-39\">三十九 · 精度塌陷：预算函数在低精度采样路径上的失稳</h3>\n<p>CoBA-RL 的预算函数本身是连续的，但它在部署中执行的位置决定了失败形态。生成侧按能力估计给出 token 配额，验证侧按同一估计给出验证次数配额，两侧共享同一个 <span class=\"formula\">$$\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)$$</span> 的输入 <span class=\"formula\">$$c_i$$</span>。精度塌陷的典型现场是：生成端用低精度数值路径（NVFP4 或 FP8）采样，验证器服务用另一条数值路径打分，两条路径对同一候选的分数分布出现系统性偏移。此时预算分配把更多验证次数投向能力边界样本，而这些样本恰好是分数偏移最敏感的区间——边界样本的候选分布窄，采样偏差直接改变排序，验证预算再多也只是在错误排序上重复确认。</p>\n<p>诊断的第一步不是看吞吐，而是看「同候选双路径打分差」。工程上可做影子校验：对每个批次抽取固定比例候选，同时送低精度生成路径与高保真验证路径，记录分数差的分布。若分数差随 <span class=\"formula\">$$c_i$$</span> 接近 <span class=\"formula\">$$\\tau$$</span> 而放大，说明塌陷发生在阈值邻域，而非全局。第二步看验证通过率随预算档位的变化：正常情况验证次数增加应带来通过率单调上升后饱和；若出现「预算翻倍、通过率不升反降」，即为精度塌陷的强信号。代价侧，影子校验占用验证器服务容量，按批次抽 1%–5% 候选是可控的，但会把验证服务的尾延迟抬高，需与长尾队列深度一起看。</p>\n<p>具体例子：某批中 <span class=\"formula\">$$c_i$$</span> 落在 <span class=\"formula\">$$\\tau$$</span> 附近的一组长尾数学样本，生成端 NVFP4 采样得到多个近似等价候选，验证器在高保真路径下给出几乎相同的分数，排序由数值噪声决定。调度器按预算函数给这组样本较大验证配额，验证服务被打满，而通过率没有改善——表现为「验证容量被边界样本吃掉、吞吐下降、精度不升」。定位方法是把该组样本的 <span class=\"formula\">$$c_i$$</span> 分布与分数差分布叠图，若两者在 <span class=\"formula\">$$\\tau$$</span> 邻域同时出现尖峰，即可判定为阈值邻域的精度塌陷，处置是把 <span class=\"formula\">$$T$$</span> 调大以平滑映射，或对该邻域样本改走高保真采样路径。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-40\">四十 · OOM 与显存抖动：前缀 KV 复用与配额队列的耦合</h3>\n<p>OOM 在 CoBA-RL 的部署形态里很少是单请求造成的，而是配额队列与前缀 KV 复用叠加的结果。生成侧按预算配额组批，长尾样本进入受限配额队列；前缀共享让多个候选复用同一段 KV，显存占用取决于「活跃前缀数 × 前缀长度 × 每 token KV 字节」加上「配额队列中等待样本的预留」。预算函数把大配额给能力边界样本，这些样本生成长、前缀复用命中率低，KV 增长快；而简单样本快速通过验证后其 KV 未必及时释放，形成碎片。</p>\n<p>诊断顺序应为：先看批利用率与配额队列深度的乘积，若批利用率下降而队列深度上升，说明组批被长尾样本拖住、显存被等待样本的预留占住；再看前缀复用命中率，命中率下降通常先于 OOM 出现。工程上可用的判据是「显存增长斜率与生成 token 数之比」，正常应接近线性；若斜率在某个 <span class=\"formula\">$$c_i$$</span> 档位突然抬升，说明该档位的样本前缀长度分布异常，配额给得过大。</p>\n<p>具体例子：一批混合难度样本中，少数超长样本获得 <span class=\"formula\">$$\\mathcal{B}_{\\max}$$</span> 配额，前缀复用因候选间差异大而失效，KV 按全长增长；同时简单样本的 KV 因验证回传延迟未释放。调度器继续按配额组批，显存逼近上限，触发 OOM 或强制驱逐，驱逐又造成重算，吞吐塌陷。处置不是简单调小 <span class=\"formula\">$$\\mathcal{B}_{\\max}$$</span>，而是把长尾配额队列的预留显存与活跃前缀显存分开计量，并对配额队列设硬上限——队列满时新长尾样本降级到小配额或延后，避免等待样本的预留把活跃批挤爆。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-41\">四十一 · 批抖动：阈值与温度联合调参的稳定性代价</h3>\n<p>批抖动指相邻批次的组批形态剧烈变化：批大小、平均生成长度、验证请求量在批间大幅摆动，导致 GPU 利用率与验证服务负载呈锯齿。根因在预算函数的斜率。对 <span class=\"formula\">$$c_i$$</span> 求导可得 <span class=\"formula\">$$\\frac{\\partial \\mathcal{B}_i}{\\partial c_i}=\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\frac{1}{T}\\,\\sigma'\\!\\left(\\frac{c_i-\\tau}{T}\\right)$$</span>，当 <span class=\"formula\">$$T$$</span> 偏小，阈值邻域的斜率极大，能力估计的微小更新就把样本从最小配额推到最大配额，组批形态随之跳变。冷启动阶段能力估计未收敛，这种跳变更频繁。</p>\n<p>诊断批抖动要看三个序列的批间方差：批大小、平均生成 token 数、验证请求数。若三者方差同步放大，且放大出现在能力估计更新之后，即为预算函数斜率问题而非负载问题。代价是双向的：<span class=\"formula\">$$T$$</span> 调大平滑了抖动但压缩了预算区分度，算力从边界样本回流到简单样本，能力导向的收益被稀释；<span class=\"formula\">$$T$$</span> 调小则抖动加剧，批利用率与验证服务利用率都下降。</p>\n<p>具体例子：能力估计每轮更新后，一批原本 <span class=\"formula\">$$c_i&lt;\\tau$$</span> 的样本越过阈值，配额从 <span class=\"formula\">$$\\mathcal{B}_{\\min}$$</span> 跳到接近 <span class=\"formula\">$$\\mathcal{B}_{\\max}$$</span>，该批平均生成长度骤增，调度器组出的批变小、批利用率下降，同时验证请求量骤增打满验证服务。下一轮估计回摆，形态又反向跳变。处置是给预算函数加更新阻尼：能力估计按指数滑动平均更新后再进预算函数，并对单轮配额变化设上限，使组批形态的变化率受控；同时把 <span class=\"formula\">$$T$$</span> 与 SLO 联合调参，用长尾队列深度作为反馈量而非固定超参。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-42\">四十二 · 尾延迟与静默降级：长尾队列深度作为主监控量</h3>\n<p>尾延迟在 CoBA-RL 中主要来自长尾样本的配额等待与验证服务的多次打分。受限配额队列避免了单个超长样本独占批资源，但代价是长尾样本的端到端延迟被队列深度直接放大。监控上应把「长尾队列深度」与「批利用率」作为一对主指标：队列深度上升而批利用率下降，说明长尾样本在等配额、活跃批没吃饱；队列深度上升而批利用率不变，说明长尾样本在等验证服务，瓶颈在验证侧而非生成侧。</p>\n<p>静默降级是更隐蔽的失败：系统没有报错、没有 OOM，但预算分配实际退化为均匀配额。触发条件有三类——能力估计冷启动未收敛，预算函数输出集中在区间中部；长尾配额队列过紧，困难样本被反复延后直至被丢弃，实际采样分布偏向简单样本；异步流水线权重同步点版本对齐失败，过期候选被丢弃后预算重排回均匀。三类降级的共同表征是「预算分布熵上升、能力估计与配额的相关性下降」。诊断方法是持续记录 <span class=\"formula\">$$c_i$$</span> 与 <span class=\"formula\">$$\\mathcal{B}_i$$</span> 的秩相关系数，正常应显著为正；若相关系数趋近零，即为静默降级。</p>\n<p>具体例子：异步流水线权重同步频率偏低，离策略陈旧度累积，超阈值候选被批量丢弃，调度器为填满批把预算重排为均匀配额，长尾样本不再受配额约束，单个超长样本重新独占批资源，尾延迟抬升而吞吐表面不变——监控只看吞吐会漏掉这次降级。处置是把秩相关系数与离策略陈旧度一起纳入告警，任一越界即触发预算收缩或版本对齐。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-43\">四十三 · 定位与回滚：版本对齐点作为回滚锚</h3>\n<p>定位的工程路径应围绕权重同步点组织，因为它是生成侧、验证侧与预算重排三者版本一致性的唯一锚。一次异常批次的可疑来源有四个：能力估计更新、预算函数参数（<span class=\"formula\">$$\\tau$$</span>、<span class=\"formula\">$$T$$</span>、区间）、生成侧数值路径、验证器服务版本。定位时按「同候选跨版本重放」缩小范围：固定候选集，分别在当前版本与上一同步点版本下重跑生成与验证，比较分数差与配额分配，若差异只在配额侧，则问题在预算函数或能力估计；若差异在分数侧，则问题在数值路径或验证器。</p>\n<p>回滚锚应设在权重同步点而非单次配置变更，因为预算重排与版本对齐是联动的：单独回滚预算参数而不回滚能力估计，会造成配额与估计错配；单独回滚验证器而不回滚生成侧数值路径，会重新引入精度塌陷。回滚的代价必须提前计量——回滚到上一同步点意味着丢弃该窗口内的候选与预算重排结果，长尾队列中的等待样本需要重新配额，尾延迟在回滚窗口内抬升。工程判断是：把回滚窗口长度与长尾队列深度绑定，队列越深回滚代价越大，因此同步频率应在「离策略陈旧度可控」与「回滚代价可承受」之间取折中，而非一味提高同步频率。</p>\n<p>具体例子：某轮出现验证通过率下降且秩相关系数走低，按同步点重放发现分数差集中在 <span class=\"formula\">$$\\tau$$</span> 邻域，判定为生成侧数值路径与验证器不一致。处置分两步：先把该邻域样本临时改走高保真采样路径止血，再在下一同步点统一数值路径并回滚预算参数至上一锚点；回滚期间长尾队列深度上升，需同步放宽配额队列上限以避免困难样本被丢弃造成二次降级。整个处置以同步点为界，保证生成、验证、预算三者版本一致，避免局部回滚引入新的错配。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-44\">四十四 · 失效面：预算函数的三个断点与回滚判据</h3>\n<p>CoBA-RL 的预算函数本身是平滑的，但工程失效往往发生在映射的两端与中间阈值处。第一类断点是<b>精度塌陷</b>：材料未给出量化方案，若 rollout 侧在 NVFP4 下采样、而验证器服务走另一条数值路径，同一候选在两侧打分不一致，能力估计 $c_i$ 被系统性污染，预算分配反而把算力推向被低估的困难样本。诊断上应做<b>双路径一致性探针</b>——周期性把同一批候选同时送入高精度参考路径与生产路径，比较分数差的分布；一旦分布尾部变厚，说明采样数值路径已与验证器脱钩，此时预算函数的输出不再可信。代价是探针流量占用验证服务容量，需按验证预算的固定比例预留，不能挤占边界样本的多次验证配额。</p>\n<p>第二类断点是<b>长尾配额与批抖动的耦合</b>。受限配额队列把超长样本挡在批外，但配额阈值与 SLO 必须联合调参：配额过紧，困难样本被欠采样，能力估计长期停在低分区，预算收缩自我强化；配额过松，单个超长样本重新独占批资源，批利用率塌陷。可用的定位量是<b>批有效占用率</b>，定义为批内实际参与计算的 token 数与按配额上限组批的名义 token 数之比：</p>\n<div class=\"formula\">$$\\eta=\\frac{\\sum_{i\\in \\text{batch}}\\min(t_i,\\mathcal{B}_i)}{\\sum_{i\\in \\text{batch}}\\mathcal{B}_i}$$</div>\n<p>$\\eta$ 持续走低且长尾队列深度同步上升，说明配额在保护长尾的同时牺牲了组批效率，应触发预算扩张而非继续收缩。第三类断点是<b>静默降级</b>：异步流水线在权重同步点丢弃过期候选并重排预算，若丢弃率上升而监控只看吞吐，系统会表现为“跑得动但学不动”——候选被静默替换成旧版本策略的产物，离策略陈旧度累积。定位手段是把丢弃率、版本差与长尾队列深度三者做成同一条时间线，任一指标越界即冻结预算扩张。</p>\n<p>回滚判据应绑定机制而非结果：当双路径一致性探针的分数差尾部越界、或 $\\eta$ 与长尾队列深度同向恶化、或丢弃率超过版本对齐窗口所能吸收的范围时，回滚到均匀配额并降低权重同步频率，先恢复采样稳定性再重新放开能力预算。材料未给出具体阈值，因此这些判据只能以相对基线的漂移量表达；在缺少硬件档位与量化配置的情况下，任何绝对吞吐承诺都不成立，工程上应把预算函数视为可热切换的策略层，而不是写死在调度器里的常量。</p>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-45\">四十五 · 口径的第一性问题：这篇论文没有可比的绝对数字</h3>\n<p>读 CoBA-RL 的基准部分，必须先接受一个前提：论文材料里没有数据集名称、没有基线名称、没有硬件档位、没有并行拓扑、没有量化方案，也没有任何可核验的吞吐、SLO 或采样稳定性数字。这意味着任何“CoBA-RL 比统一预算快 X%”的说法都是编造。可核验的只有机制层：预算函数把能力估计 $c_i$ 经阈值 $\\tau$ 与温度 $T$ 平滑映射到区间 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$，调度器按该配额组批，长尾样本进入受限配额队列，验证预算与生成预算分离下发到独立验证服务。因此本部分的“基准与口径”不是复述一张结果表，而是给出一个读法框架：哪些量可以从机制推断方向，哪些量必须等硬件与量化数据补齐才能比较，哪些跨论文数字天然不可比。</p>\n<p>对工程读者而言，最危险的不是论文缺数字，而是把缺数字的机制描述误读成性能结论。CoBA-RL 的收益在材料中只能从调度机制层面推断：把算力从已掌握样本转移到能力边界样本，并用配额队列隔离长尾。这条推断链的每一环都依赖部署形态——rollout 引擎与训练解耦、异步流水线、权重同步点版本对齐——一旦硬件档位或量化路径改变，方向可能反转。下面按“模型与负载口径、硬件档位口径、batch 与并发口径、指标口径、不可比清单”五层拆开。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-46\">四十六 · 模型与负载口径：能力估计是隐变量，不是基准配置</h3>\n<p>CoBA-RL 的“模型”口径有两层：被推理的策略模型，以及作为独立推理服务运行的奖励模型与验证器。材料未给出两者的规模、并行拓扑与量化方案，因此不能假设验证器与策略模型共享同一数值路径。这一点直接决定基准怎么读：预算函数作用在样本级，$c_i$ 是能力估计，$\\tau$ 是能力阈值，$T$ 是平滑温度；$\\sigma$ 把 $c_i$ 压到 $[0,1]$ 后线性映射到 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$。当 $c_i \\ll \\tau$ 时预算趋近下界，样本快速通过验证；当 $c_i$ 接近 $\\tau$ 时预算落在区间中部，边界样本获得多次验证。负载口径上，请求长度分布与长尾比例材料未给出，只能确定长尾样本受配额约束、不独占批资源。</p>\n<p>这里有一个常被忽略的口径问题：能力估计的更新方式未说明，冷启动阶段预算分配可能偏向均匀配额。也就是说，基准测试若在冷启动窗口内采样，测到的接近统一预算的行为，而非能力导向分配的行为；若在能力估计收敛后采样，才可能看到预算向边界样本集中。读任何 CoBA-RL 风格的结果，都要先问“能力估计处于哪个阶段”，否则同一套调度在不同时间窗内给出不同吞吐曲线。代价侧，能力估计本身若需一次额外前向或历史统计，就引入每样本的固定开销；材料未给出该开销的量级，因此不能把它算进 TTFT 预算。</p>\n<div class=\"formula\">$$\\mathcal{B}_{i}=\\mathcal{B}_{\\min}+\\left(\\mathcal{B}_{\\max}-\\mathcal{B}_{\\min}\\right)\\cdot\\sigma\\!\\left(\\frac{c_{i}-\\tau}{T}\\right)$$</div>\n<p>举例：一个已掌握样本 $c_i$ 远低于 $\\tau$，预算贴近 $\\mathcal{B}_{\\min}$，生成少量 token 即送验证；一个能力边界样本 $c_i \\approx \\tau$，预算落在区间中部并配多次验证。两者在同一批中并存时，批的 token 总量由配额之和决定，而不是由最大样本长度决定——这正是配额队列要解决的整批等待问题。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-47\">四十七 · 硬件档位口径：没有档位就没有 NVFP4 结论</h3>\n<p>材料明确未给出硬件档位、并行拓扑与量化方案，因此 NVFP4 下采样稳定性与显存占用无法核验。对 Blackwell 读者，这一条必须写死：不能把 CoBA-RL 的调度收益直接叠加到 SM100/SM103 的 NVFP4 推理路径上，因为预算分配改变的是每样本 token 配额与验证次数，而 NVFP4 改变的是数值路径与显存带宽占用；两者交互点在“采样数值路径与验证器是否一致”。若策略模型在 NVFP4 下采样、验证器在另一精度下打分，预算分配带来的吞吐收益可能被采样偏差抵消——这是材料列出的失败模式之一，但阈值与量级未给出。</p>\n<p>硬件档位口径还影响长尾队列的物理意义。受限配额队列在 B200 单卡、GB200 NVL72 机架、乃至多机分离式部署下的排队代价不同：单卡上队列深度直接映射到 SM 占用与批利用率；NVL72 上跨 NVLink 5 的验证服务调用引入额外通信跳数，验证预算的分配就从“算力配额”变成“通信配额”。材料未给出并行拓扑，所以无法判断验证服务是共卡、共节点还是跨机架。工程判断上，读这类论文时应把“验证算力与生成算力分离”理解为拓扑待定的设计意图，而不是已测得的分离式收益。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>材料状态</th><th>可推断</th><th>不可推断</th></tr></thead><tbody><tr><td>硬件档位</td><td>未给出</td><td>部署形态为 rollout 与训练解耦</td><td>SM100/SM103 上的吞吐与功耗</td></tr><tr><td>量化方案</td><td>未给出</td><td>KV 策略为前缀复用与共享</td><td>NVFP4 采样稳定性、显存占用</td></tr><tr><td>并行拓扑</td><td>未给出</td><td>验证器为独立推理服务</td><td>跨 NVLink/NCCL 的验证通信代价</td></tr><tr><td>batch/并发</td><td>未给出</td><td>长尾样本进入受限配额队列</td><td>批大小上限与批利用率绝对值</td></tr></tbody></table>\n<p>代价侧的具体例子：若验证服务与 rollout 引擎共卡，验证预算增加会挤占生成侧的 KV cache 空间，长尾队列深度上升；若分离部署，验证预算增加转化为跨节点请求，TTFT 不受影响但端到端时延受通信支配。两种拓扑下同一预算函数的吞吐方向可能相反，这正是“档位未给出则收益不可比”的实质。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-48\">四十八 · batch 与并发口径：配额组批改变的是批的构成</h3>\n<p>CoBA-RL 的批调度不是按请求到达顺序组批，而是按预算配额组批：调度器读取每个样本的能力估计，给出生成 token 配额与验证次数配额，再据此组批。材料未给出批大小与并发上限，但机制上可推断两件事。第一，批的 token 总量近似为各样本配额之和，长尾样本被限制在配额队列内，因此单个超长样本不会占满批导致整批等待——这是吞吐侧的主要工程代价，也是与连续批处理（其他部分已讲）不同的地方：这里限制的是单样本配额，而非批内请求数。第二，验证预算按样本分配，验证请求与生成请求在时间上解耦，异步流水线回传结果，权重同步点对齐版本。</p>\n<p>并发口径的关键是离策略陈旧度。异步流水线下，候选在旧权重版本上生成、在新版本上验证，陈旧度超阈值则丢弃过期候选并重排预算；材料未给出具体阈值与权重同步频率，因此无法评估偏差量级。可推断的是：预算重排必须与版本对齐联动，否则长尾样本在队列中等待期间跨过多个权重版本，其能力估计与当前策略脱节，配额失去意义。工程上这意味着监控项至少包含长尾队列深度、批利用率与离策略陈旧度三项，材料确认这三项被记录，用于下一轮预算收缩或扩张。</p>\n<p>伪代码思路：调度器对批内样本按 $c_i$ 排序，先填充低配额样本以快速周转，边界样本进入中部配额槽，长尾样本进入受限队列并设深度上限；每轮结束时若长尾队列深度超阈值则收缩困难样本预算，若批利用率偏低则扩张。代价是排序与配额计算本身的调度开销，以及配额队列带来的批构成碎片化——批内样本预算差异越大，批的有效利用率越难维持，这是能力导向分配固有的吞吐税。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-49\">四十九 · 指标口径：TTFT/TPOT/吞吐/显存/功耗各自被什么改变</h3>\n<p>在 CoBA-RL 的机制下，五个指标受不同环节支配，不能混为一谈。TTFT 主要由预填与前缀 KV 复用决定：候选经前缀 KV 复用生成，减少重复预填，因此前缀共享命中率高的负载 TTFT 下降；但预算分配本身不改变单请求预填量，能力估计若需额外前向则抬升 TTFT。TPOT 由解码步与批内并发决定：配额组批使批内样本预算差异大，解码步的有效 token 产出不均，TPOT 的方差上升而均值方向不定。吞吐由批利用率与长尾隔离决定：长尾不独占批资源是吞吐侧的主要收益来源，但配额过紧会欠采样困难样本，过松则失去吞吐收益，阈值需与 SLO 联合调参。</p>\n<p>显存与功耗口径最容易被误读。材料未给出量化方案，显存占用无法核验；可推断的是 KV 复用与前缀共享降低重复预填的显存带宽压力，而验证服务作为独立推理服务占用额外显存或跨节点带宽。功耗侧，验证预算增加意味着额外推理服务活跃时间延长，若验证与生成共卡则功耗峰值叠加；材料未给出功耗数据，因此任何“更省电”的说法都不成立。指标读法上，应把吞吐收益归因到“长尾隔离 + 配额组批”，把 TTFT 收益归因到“前缀 KV 复用”，把不确定性归因到“验证服务拓扑与量化路径未定”。</p>\n<div class=\"formula\">$$\\text{批有效利用率}\\;\\approx\\;\\frac{\\sum_{i\\in\\text{batch}}\\min(\\mathcal{B}_i,\\;\\text{已生成}_i)}{\\max_{i\\in\\text{batch}}\\mathcal{B}_i\\cdot|\\text{batch}|}$$</div>\n<p>举例：一批中三个样本配额分别为下界、中部、上界，若上界样本被长尾队列截断，批的有效利用率由中部样本填充；若不做配额隔离，上界样本独占批，有效利用率被单样本拉低。这个比值是读吞吐数字时的归因工具，而非论文给出的实测指标。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-50\">五十 · 不可比清单：哪些提升不能跨论文、跨档位相加</h3>\n<p>第一类不可比是“无基线的相对提升”。材料未给出基线名称，因此 CoBA-RL 相对统一预算的收益只能从机制推断，不能与任何具体 PPO/GRPO 变体的报告数字并列。第二类是不可比的硬件档位：未给出 SM100/SM103 配置与量化方案，NVFP4 采样稳定性无法核验，因此不能把调度收益与 Blackwell 算子收益相乘。第三类是不可比的负载：请求长度分布与长尾比例未给出，长尾隔离的收益高度依赖长尾占比，长尾少的负载上配额队列近乎无收益。第四类是不可比的异步口径：离策略陈旧度阈值与权重同步频率未给出，异步流水线的偏差量级未知，跨论文比较异步吞吐时必须对齐陈旧度定义。</p>\n<p>第五类是不可比的验证口径：验证预算按样本分配，但验证器的模型规模、精度与拓扑未给出；验证算力与生成算力分离的设计在不同拓扑下代价不同，验证次数翻倍在共卡部署上挤占生成 KV cache，在分离部署上只增加通信。第六类是不可比的冷启动口径：能力估计更新方式未说明，冷启动窗口内预算偏向均匀，测得的曲线接近统一预算行为。工程判断上，读 CoBA-RL 应把它当作“调度机制的可迁移思路”，而不是“已测得的吞吐结论”；可迁移的是配额组批、长尾受限队列、验证预算分离与版本对齐联动这四件事，需要补齐的是硬件档位、量化方案、数据集与基线，才能把机制收益转成可核验数字。</p>\n<p>最后落在具体机制上：预算函数的阈值 $\\tau$ 与温度 $T$ 是这套口径的调节旋钮，$\\tau$ 决定多少样本被视为“已掌握”而进入低配额，$T$ 决定边界样本的配额过渡宽度；两者与 SLO 联合调参，配额过紧欠采样困难样本，过松失去吞吐收益。在硬件与量化数据补齐之前，任何把这套旋钮的调节说成“提升百分比”的读法都不成立——能成立的只有：长尾样本不独占批资源这一条，是吞吐侧唯一可从机制直接推断的工程代价与收益来源。</p>\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-51\">五十一 · 迁移的第一道坎：能力估计从哪里来</h3>\n<p>CoBA-RL 的预算函数本身是模型无关的，真正决定它能否迁移的是 $c_i$ 的来源。原文只给出 $c_i$ 经阈值 $\\tau$ 与温度 $T$ 映射到 $[\\mathcal{B}_{\\min},\\mathcal{B}_{\\max}]$，没有说明 $c_i$ 如何更新、冷启动如何初始化。这意味着迁移到新模型或新领域时，第一件要改的不是预算公式，而是能力估计的产出通道。工程上有三条可选路径：用历史 rollout 的通过率做指数滑动平均、用同批次内已完成的验证分数做在线回填、用离线小样本评测给出先验。三条路径的代价完全不同——滑动平均需要跨批次状态存储，在线回填要求验证服务与调度器之间有低延迟回传通道，离线先验则在领域漂移时迅速失效。判断标准很直接：如果新领域的样本通过率在批次间波动大于预算区间宽度的一半，滑动平均就会被噪声主导，此时应改用在线回填并接受验证服务侧的额外排队延迟。</p>\n<p>冷启动偏差是迁移中最容易被忽略的代价。原文承认冷启动阶段预算分配可能偏向均匀配额，这在工程上等价于退化为统一预算方案，即 CoBA-RL 想替代的旧做法。迁移到新领域时，如果前若干批次全部落在均匀配额区，长尾样本仍会独占批资源，吞吐收益为零。可行的做法是在冷启动期人为压低 $\\mathcal{B}_{\\max}$、抬高 $\\mathcal{B}_{\\min}$，缩小预算区间，让调度器先积累能力估计再放开区间；代价是边界样本在前若干批次被欠采样，收敛信号变弱。这是一个明确的取舍，不是可以两全的参数。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-52\">五十二 · 验证预算迁移：验证器换掉之后配额要重算</h3>\n<p>验证预算与生成预算分离是这套方案的结构性优点，也是迁移时最脆弱的一环。原文把奖励模型与验证器作为独立推理服务，按样本分配验证次数。换领域时验证器的单次调用成本会变：数学题可以用规则校验，成本接近零；开放域对话需要奖励模型前向，单次成本与序列长度成正比；多步工具调用需要执行环境，成本含外部 I/O 等待。验证预算的配额若沿用原领域的次数，会在新领域产生两种错误：规则校验类领域配额过剩，验证服务空转；执行环境类领域配额不足，边界样本只验证一次就被判定，能力估计被单次噪声污染。</p>\n<p>可操作的迁移规则是把验证配额从“次数”改为“成本上限”。设单次验证成本为 $v_j$，样本 $i$ 的验证预算为 $V_i$，则约束写成</p>\n<div class=\"formula\">$$\\sum_{i \\in \\text{batch}} V_i \\cdot v_{j(i)} \\le C_{\\text{verify}}$$</div>\n<p>调度器在组批时同时满足生成配额与这条成本约束。代价是组批从一维装箱变成二维约束，批利用率会下降，尤其当批内验证器类型混杂时。工程判断：如果新领域的验证器类型单一，二维约束退化为按成本缩放的次数配额，迁移成本低；如果类型混杂，应把验证服务按类型分池，各自独立组批，避免一个慢验证器拖住整批。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-53\">五十三 · 长尾配额与 SLO 的联合调参：迁移时阈值必须重估</h3>\n<p>长尾样本进入受限配额队列是吞吐侧的主要机制，也是迁移时最容易失效的机制。原文明确指出长尾配额过紧会欠采样困难样本，过松则失去吞吐收益，阈值需与 SLO 联合调参。迁移到新领域时，长度分布与长尾比例都会变，原阈值不再对应原来的队列深度。判断方法不是调 $\\tau$，而是先测新领域的长尾队列深度分布：若 P99 长度是 P50 的数倍，受限队列的容量必须按 P99 而非均值设定，否则长尾样本在队列内排队的时间会超过其生成时间，配额机制反而成为延迟来源。</p>\n<p>这里有一个具体的工程代价需要说清：受限配额队列把长尾样本从主批中隔离，主批的批利用率上升，但长尾样本的完成时间被推迟。如果 SLO 约束的是端到端 P99 延迟，隔离策略会把 P99 推向长尾队列的排空时间；如果 SLO 约束的是吞吐，隔离是净收益。迁移前必须确认 SLO 的口径，否则会把一个吞吐优化误装到延迟敏感场景上。原文的材料未给出 SLO 目标与验证预算配额，因此无法从论文直接读出这套机制在延迟口径下的表现，只能从队列结构推断。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-54\">五十四 · 异步流水线与离策略陈旧度：迁移到高同步频率场景要改</h3>\n<p>异步流水线在权重同步点做版本对齐，离策略陈旧度超阈值则丢弃过期候选并重排预算。这条机制的可迁移性取决于训练侧权重更新频率与 rollout 生成长度的比值。迁移到长生成、短训练步的场景（例如长链推理），单个候选的生成时间可能跨越多个权重版本，陈旧度阈值会被频繁触发，丢弃率上升，有效吞吐下降。此时要么降低同步频率、接受更大的陈旧度偏差，要么缩短单样本生成预算、把长样本拆成多段验证。前者牺牲采样稳定性，后者牺牲前缀 KV 复用的连续性——分段生成会打断前缀共享，重复预填代价回升。</p>\n<p>原文未给出陈旧度阈值与权重同步频率，因此迁移时不能照搬数值，只能照搬联动关系：预算重排必须与版本对齐在同一处执行，否则调度器会按旧版本的能力估计给新版本的候选分配配额，产生系统性偏差。工程上可监控的量是丢弃率与长尾队列深度的联合分布——丢弃率上升而队列深度不变，说明阈值过紧；两者同时上升，说明生成预算与同步频率不匹配，需要改的是预算区间而不是阈值。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-55\">五十五 · 规模上限：这套方案在哪里先失效</h3>\n<p>规模上限不在预算函数，而在能力估计的信噪比与验证服务的吞吐。随着并发规模上升，单样本的验证次数被摊薄，能力估计的方差增大，预算分配的区分度下降，最终退化为均匀配额。这个退化点可以用一个粗略判据定位：当批内样本数乘以平均验证次数超过验证服务在 SLO 窗口内的处理能力时，验证预算被迫压缩，能力估计更新变慢，预算分配失去意义。此时扩容验证服务比调预算函数更有效，但验证服务本身是独立推理服务，扩容意味着额外的显存与功耗预算，与 rollout 引擎争抢同一批 GPU。</p>\n<p>另一个上限来自前缀 KV 复用的命中率。预算分配把边界样本的生成预算拉大，这些样本的前缀往往更长、更独特，前缀共享的命中率低于简单样本。规模越大，边界样本占比越高，KV 复用的边际收益越低，显存占用上升。原文未给出量化方案与硬件档位，NVFP4 下采样稳定性与显存占用无法核验，因此这条上限只能定性判断：在 KV 复用命中率随规模下降的场景里，预算分配的吞吐收益会被显存压力抵消，迁移前应先测命中率曲线而不是先调 $\\tau$ 与 $T$。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-56\">五十六 · 不适用的边界与迁移判断</h3>\n<p>有三类场景不适合直接迁移。第一类是验证成本远高于生成成本的场景，例如需要外部执行环境的智能体任务：验证预算的成本约束会主导组批，生成预算的分配失去杠杆，CoBA-RL 的结构优势被验证侧瓶颈吞掉。第二类是样本能力在批次内几乎无差异的场景，例如固定难度的合成数据：能力估计的区分度不足，预算函数退化为常数，调度复杂度白付。第三类是延迟口径极严、批利用率本就低的场景：长尾隔离队列会进一步拉低批利用率，配额机制成为纯开销。</p>\n<p>迁移的正确顺序是先改能力估计通道，再改验证配额的成本口径，最后重估长尾阈值与陈旧度联动；预算函数的区间与温度放在最后调，因为它的敏感性原文未量化，先调它等于在噪声上做优化。判断这套方案是否值得迁移，看一个指标即可：新领域内简单样本与边界样本的验证通过率差距是否足够大。差距大，算力从已掌握样本转移到边界样本的收益成立；差距小，统一预算的调度开销更低。这个判断不需要硬件档位数据，只需要一批带验证分数的历史样本。</p>\n\n<h3 id=\"paper-coba-rl-capability-oriented-budget-a-2026-sec-57\">五十七 · 迁移到别的模型与领域时要动哪三处</h3>\n<p>这套预算分配的可迁移内核只有一层：把「每样本算力」从常数改成能力估计的函数，并在组批层与验证服务层各执行一次。迁到别的模型时，真正要改的不是公式，而是公式的输入与执行点。输入侧，能力估计 $c_i$ 的来源随模型与任务变化——分类式奖励模型给出的是标量偏好分，验证器给出的是可判定的通过/失败，代码与数学任务还能拿到执行反馈，而开放式生成只能依赖奖励模型打分，噪声更大、区分度更低。此时阈值 $\\tau$ 与温度 $T$ 的标定必须重做：$T$ 过小则预算映射接近硬切换，简单样本与边界样本被切成两簇，组批时批内 token 长度方差骤增；$T$ 过大则预算趋近均匀，退化为原有的统一预算方案。执行点侧，若目标框架不支持按请求设置 token 上限与验证次数，预算只能落在调度器外部做准入控制，长尾配额队列就变成框架之外的旁路，KV 前缀共享的收益也随之打折。</p>\n<p>迁到别的领域时，失效条件集中在两类。第一类是验证本身昂贵且不可分割的领域，例如需要跑完整测试套件或多轮工具调用的 agent 任务：验证预算按「次数」分配，但单次验证的代价远高于生成一个候选，预算函数对生成侧的调节失去意义，真正的瓶颈在验证服务队列，此时应把预算函数改写到验证并发度上，而不是 token 配额。第二类是长尾分布极端的领域，例如超长文档理解或长链推理，受限配额队列会把困难样本压到极低采样率，能力估计因缺少样本而无法更新，形成「越难越不采、越不采越估不准」的闭环。可用一个粗判据：设长尾样本占比 $p$、单样本超长概率 $q$，则批内被长尾拖住的期望等待与 $p\\cdot q$ 同阶；当 $p\\cdot q$ 超过批利用率可容忍的抖动幅度时，配额队列的收益被欠采样偏差吃掉。</p>\n<p>规模上限不在预算函数本身，而在异步流水线的版本对齐粒度。rollout 与训练解耦后，权重同步点之间的候选带有离策略陈旧度；预算重排若发生在同步点之外，就会出现「用旧能力估计给新权重分配预算」的错配。规模越大、同步越稀，这一错配越显著，且论文未给出陈旧度阈值与同步频率，无法据此定标。工程判断是：把预算重排绑定到版本对齐事件上，而不是按固定步数触发；监控侧的长尾队列深度与批利用率应作为收缩/扩张预算的反馈信号，与 SLO 联合调参，而非单独调 $\\tau$。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>需改动</th><th>不适用信号</th></tr></thead><tbody><tr><td>能力估计来源</td><td>重标 $\\tau$、$T$；引入执行反馈</td><td>奖励分区分度低，预算趋均匀</td></tr><tr><td>验证代价</td><td>预算改写到验证并发度</td><td>单次验证代价远高于生成</td></tr><tr><td>长尾比例</td><td>放宽配额或改分组组批</td><td>欠采样导致能力估计停滞</td></tr><tr><td>异步深度</td><td>预算重排绑定版本对齐</td><td>陈旧度超阈值仍重排</td></tr></tbody></table>\n<p>量化与硬件档位是另一条硬边界：论文未给出并行拓扑与量化方案，NVFP4 下采样数值路径若与验证器不一致，预算分配的收益会被采样偏差抵消，这类风险在迁移到新硬件时只能靠端到端一致性校验暴露，不能从调度机制层面推断。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 155\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"69.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">CoBA-RL: </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Capability-Oriented Budget</text><text x=\"292.0\" y=\"95.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\"> All…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"82.5\" x2=\"271.0\" y2=\"82.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 78.0 L 270.0 87.0 L 278.0 82.5 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"82.5\" x2=\"515.0\" y2=\"82.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 78.0 L 514.0 87.0 L 522.0 82.5 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"145.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · CoBA-RL: Capability-Ori… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线名称</td></tr><tr><td>主要结果</td><td>材料未给出可核验的吞吐、SLO 或采样稳定性数字，仅能确认预算分配在批量调…</td></tr><tr><td>消融</td><td>材料未给出消融实验设置与结果，预算函数中阈值与温度的敏感性未量化。</td></tr><tr><td>局限</td><td>材料未给出硬件档位、并行拓扑与量化方案，无法核验 NVFP4 下采样稳定性…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-coba-rl-capability-oriented-budget-a-2026 · 共 9 个片段</p>\n";break;}}})();
